// V3 is an additive extension: the original workspace and its revision history stay intact.
const LENSES=[{id:'values',name:'目标与价值'},{id:'thinking',name:'认知与决策'},{id:'energy',name:'精力与情绪'},{id:'ability',name:'能力与机会'}];
const LAB_DEFAULTS={targetObservations:5,minCases:2,reviewDays:7};
function ensureLab(state){
 if(!state.lab)state.lab={schemaVersion:1,models:[],observations:[],scenarios:[],states:[],experiments:[],config:{...LAB_DEFAULTS},configHistory:[]};
 validateLab(state.lab);return state.lab;
}
function textField(x,label,max=3000){if(typeof x!=='string'||!x.trim()||x.length>max)throw Error('请填写有效的'+label+'。');return x.trim();}
function bounded(v,min,max,label){if(v===null||v===''||!Number.isFinite(Number(v))||Number(v)<min||Number(v)>max)throw Error(label+'超出范围。');return Number(v);}
function validateLab(lab){
 if(lab.schemaVersion!==1)throw Error('个人模型数据版本不正确。');
 for(const k of ['models','observations','scenarios','states','experiments','configHistory'])if(!Array.isArray(lab[k])||lab[k].length>3000)throw Error('个人模型数据集合不正确：'+k);
 const ids=new Set();for(const key of ['models','observations','scenarios','states','experiments'])for(const row of lab[key]){if(!row||typeof row.id!=='string'||ids.has(row.id))throw Error('模型记录编号不正确。');ids.add(row.id);}
 const c=lab.config;if(!c)throw Error('缺少模型规则。');bounded(c.minCases,2,20,'独立案例数');bounded(c.targetObservations,2,30,'观察目标');bounded(c.reviewDays,1,90,'回看间隔');
 for(const m of lab.models){textField(m.title,'模型名称',120);textField(m.hypothesis,'候选假设');if(!DOMAINS.some(d=>d.id===m.domain)||!Array.isArray(m.supportIds)||!Array.isArray(m.counterIds)||!['candidate','paused'].includes(m.status))throw Error('模型字段不正确。');}
 for(const o of lab.observations){if(!['actual','simulation','unknown'].includes(o.reality)||!lab.models.some(m=>m.id===o.modelId)||!['support','counter','unclear'].includes(o.stance))throw Error('观察记录性质不正确。');textField(o.context,'场景');textField(o.outcome,'结果');if(o.irritation!=null)bounded(o.irritation,0,10,'烦躁');if(o.repeats!=null)bounded(o.repeats,0,50,'重复次数');}
 for(const x of lab.scenarios)if(x.reality!=='simulation'||!Array.isArray(x.options)||!x.options.length||x.options.some(o=>!['draft','accepted'].includes(o.status)))throw Error('情景推演字段不正确。');
 return lab;
}
function saveModel(state,input,now=new Date().toISOString()){
 const lab=ensureLab(state),domain=input.domain;if(!DOMAINS.some(d=>d.id===domain))throw Error('请选择模型领域。');
 const valid=ids=>[...new Set(ids||[])].filter(id=>state.records.some(r=>r.id===id&&r.status!=='superseded'&&r.reality!=='simulation'));
 const fields={title:textField(input.title,'模型名称',120),hypothesis:textField(input.hypothesis,'候选假设'),mechanism:textField(input.mechanism,'候选机制'),boundary:textField(input.boundary,'适用边界'),alternatives:textField(input.alternatives,'替代解释'),domain,lenses:(input.lenses||[]).filter(x=>LENSES.some(l=>l.id===x)),supportIds:valid(input.supportIds),counterIds:valid(input.counterIds),updatedAt:now};
 if(fields.supportIds.some(id=>fields.counterIds.includes(id)))throw Error('同一条案例请明确支持或反驳，不能重复计入。');
 let m=lab.models.find(x=>x.id===input.id);if(m){m.versions=m.versions||[];m.versions.push({...clone(m),versions:undefined});Object.assign(m,fields,{version:m.version+1});}else{m={id:uid('model'),version:1,status:'candidate',...fields,createdAt:now};lab.models.unshift(m);}
 state.events.unshift({id:uid('event'),date:now,type:'model',title:'更新候选模型「'+m.title+'」v'+m.version});return m;
}
function recordObservation(state,input,now=new Date().toISOString()){
 const lab=ensureLab(state),m=lab.models.find(x=>x.id===input.modelId);if(!m||m.status==='paused')throw Error('请先选择使用中的候选模型。');
 if(!['actual','simulation','unknown'].includes(input.reality))throw Error('请明确这是真实发生、模拟还是未确认。');
 if(!['support','counter','unclear'].includes(input.stance))throw Error('请选择支持、反驳或暂不判断。');
 const o={id:uid('observation'),modelId:m.id,reality:input.reality,stance:input.stance,context:textField(input.context,'具体场景'),action:textField(input.action,'行动'),outcome:textField(input.outcome,'结果'),alternative:(input.alternative||'').slice(0,3000),irritation:input.irritation===''||input.irritation==null?null:bounded(input.irritation,0,10,'烦躁'),repeats:input.repeats===''||input.repeats==null?null:bounded(input.repeats,0,50,'重复次数'),understanding:(input.understanding||'未记录').slice(0,200),caseKey:textField(input.caseKey||((input.date||now.slice(0,10))+':'+input.context.trim()),'场景编号',3000),date:input.date||now.slice(0,10),createdAt:now};
 // Repeat entry of the same case never creates independent evidence.
 if(lab.observations.some(x=>x.modelId===m.id&&x.caseKey===o.caseKey&&x.reality===o.reality))throw Error('这个场景已记录；同一场景不能重复计入独立观察。');
 lab.observations.unshift(o);
 if(o.reality==='actual'){const r=addRecord(state,{title:'实验观察：'+m.title,text:'场景：'+o.context+'\n行动：'+o.action+'\n结果：'+o.outcome+'\n替代解释：'+o.alternative,domain:m.domain,type:'experience',reality:'actual',date:o.date},now);r.origin='experiment-observation';r.observationId=o.id;o.recordId=r.id;}
 state.events.unshift({id:uid('event'),date:now,type:'observation',title:(o.reality==='actual'?'真实自述观察':o.reality==='simulation'?'模拟观察':'未确认观察')+'已保存',recordId:o.recordId});return o;
}
function modelEvidence(state,id,now=new Date()){
 const lab=ensureLab(state),m=lab.models.find(x=>x.id===id);if(!m)return null;
 const caseIdentity=r=>r.observationId||r.caseKey||r.sourceRefs?.find(s=>s.id)?.id||r.id;
 const eligible=ids=>[...new Map(ids.map(id=>state.records.find(r=>r.id===id&&r.status!=='superseded'&&r.reality==='actual'&&r.provenance!=='inferred')).filter(Boolean).map(r=>[caseIdentity(r),r])).values()];
 const observations=lab.observations.filter(o=>o.modelId===id),actual=[...new Map(observations.filter(o=>o.reality==='actual'&&state.records.some(r=>r.id===o.recordId&&r.status!=='superseded')).map(o=>[o.caseKey,o])).values()];
 const supported=eligible(m.supportIds),counter=eligible(m.counterIds),uniqueCases=new Set([...supported.map(caseIdentity),...counter.map(caseIdentity),...actual.map(o=>o.id)]);
 const due=Date.parse(m.updatedAt)+lab.config.reviewDays*86400000<=+now;
 return {actual:actual.length,simulation:observations.filter(o=>o.reality==='simulation').length,unknown:observations.filter(o=>o.reality==='unknown').length,support:actual.filter(o=>o.stance==='support').length+supported.filter(r=>!actual.some(o=>o.id===r.observationId)).length,counter:actual.filter(o=>o.stance==='counter').length+counter.filter(r=>!actual.some(o=>o.id===r.observationId)).length,cases:uniqueCases.size,related:m.supportIds.length+m.counterIds.length,readyForReview:uniqueCases.size>=lab.config.minCases&&actual.length>=lab.config.targetObservations,due,label:m.status==='paused'?'已停用':uniqueCases.size>=lab.config.minCases&&actual.length>=lab.config.targetObservations?'待人工复核':'证据不足 · 候选模型'};
}
function setModelStatus(state,id,status,now=new Date().toISOString()){
 const m=ensureLab(state).models.find(x=>x.id===id);if(!m||!['candidate','paused'].includes(status))throw Error('模型状态无效。');m.status=status;m.updatedAt=now;
 state.events.unshift({id:uid('event'),date:now,type:'correction',title:(status==='paused'?'停用':'恢复候选')+'模型「'+m.title+'」'});
}
function saveCurrentState(state,input,now=new Date().toISOString()){
 const lab=ensureLab(state);const row={id:uid('state'),reality:'user_report',createdAt:now,lenses:Object.fromEntries(LENSES.map(l=>[l.id,textField(input[l.id],l.name)])),time:textField(input.time,'时间与生活约束'),sourceIds:(input.sourceIds||[]).filter(id=>state.records.some(r=>r.id===id&&r.status!=='superseded'))};lab.states.unshift(row);return row;
}
function createScenario(state,input,now=new Date().toISOString()){
 const lab=ensureLab(state);if(!lab.states.length)throw Error('先记录当前状态与约束，再做推演。');
 const options=(input.options||[]).map(o=>({id:uid('option'),action:textField(o.action,'候选行动'),prediction:textField(o.prediction,'预期变化'),cost:textField(o.cost,'成本与风险'),metric:textField(o.metric,'验证标准'),status:'draft'}));if(options.length<2||options.length>3)throw Error('请比较 2 至 3 个候选方案。');
 const row={id:uid('scenario'),title:textField(input.title,'当前问题',120),domain:input.domain,reality:'simulation',stateId:lab.states[0].id,modelIds:(input.modelIds||[]).filter(id=>lab.models.some(m=>m.id===id&&m.status==='candidate')),modelVersions:Object.fromEntries((input.modelIds||[]).map(id=>{const m=lab.models.find(m=>m.id===id);return [id,m?.version||0];})),options,createdAt:now};if(!DOMAINS.some(d=>d.id===row.domain))throw Error('请选择推演领域。');lab.scenarios.unshift(row);return row;
}
function acceptScenarioOption(state,scenarioId,optionId,now=new Date().toISOString()){
 const lab=ensureLab(state),s=lab.scenarios.find(x=>x.id===scenarioId),o=s?.options.find(x=>x.id===optionId);if(!o)throw Error('候选方案不存在。');if(o.actionId)return state.actions.find(a=>a.id===o.actionId);
 if(s.modelIds.some(id=>!lab.models.some(m=>m.id===id&&m.status==='candidate')))throw Error('引用的模型已停用，请重新推演。');
 if(s.modelIds.some(id=>s.modelVersions?.[id]&&s.modelVersions[id]!==lab.models.find(m=>m.id===id)?.version))throw Error('引用的模型已修订，请基于新版本重新比较方案。');
 const a={id:uid('action'),recordId:null,scenarioId:s.id,optionId:o.id,title:o.action,domain:s.domain,status:'active',criterion:o.metric,createdAt:now,prediction:o.prediction};o.status='accepted';o.actionId=a.id;state.actions.unshift(a);state.events.unshift({id:uid('event'),date:now,type:'action',title:'采纳推演方案「'+s.title+'」'});return a;
}
function scenarioFeedback(state,s){return s.options.filter(o=>o.actionId).map(o=>({option:o,feedback:state.feedback.find(f=>f.actionId===o.actionId)}));}
function updateLabConfig(state,input,now=new Date().toISOString()){
 const lab=ensureLab(state),next={minCases:bounded(input.minCases,2,20,'独立案例数'),targetObservations:bounded(input.targetObservations,2,30,'观察目标'),reviewDays:bounded(input.reviewDays,1,90,'回看间隔')};lab.configHistory.unshift({date:now,previous:clone(lab.config),next:clone(next)});lab.config=next;return next;
}
function memoryAudit(state){
 const l=ensureLab(state);return {pending:state.records.filter(r=>r.review==='pending'&&r.status!=='superseded'),unknown:state.records.filter(r=>r.reality!=='actual'&&r.reality!=='simulation'&&r.status!=='superseded'),simulations:state.records.filter(r=>r.reality==='simulation'),paused:l.models.filter(m=>m.status==='paused'),reviewModels:l.models.filter(m=>m.status==='candidate'&&modelEvidence(state,m.id).due)};
}
function makeDemoLab(state){
 const l=ensureLab(state);if(l.demoInitialized)return;l.demoInitialized=true;if(l.models.length)return;
 const m=saveModel(state,{title:'先确认问题，再讨论方案',domain:'build',hypothesis:'在部分评审中，先确认用户任务可能减少无效功能讨论。',mechanism:'先建立共同问题表述，可能让后续讨论更集中；目前只是虚构演示。',alternatives:'议题难度、参会者经验、时间限制也可能影响评审。',boundary:'仅用于体验流程。不能据此推断真实用户或你的稳定行为。',lenses:['thinking','ability'],supportIds:['demo-1','demo-4'],counterIds:[]});
 l.experiments.push({id:'demo-experiment',code:'DEMO-01',modelId:m.id,title:'虚构评审练习',protocol:'下一次先复述用户场景，再记录实际讨论是否更集中。本示例不计真实实践。'});
 saveCurrentState(state,{values:'虚构样例：希望把模糊想法变成可验证的小项目。',thinking:'虚构样例：讨论功能前，先判断哪个问题最需要验证。',energy:'虚构样例：精力有限，给验证留出恢复与回看时间。',ability:'虚构样例：已有一份评审草稿，需要补充真实场景。',time:'虚构样例：本周安排一次 20 分钟小练习。',sourceIds:['demo-1']});
 createScenario(state,{title:'怎样让下一次评审更聚焦？（虚构样例）',domain:'build',modelIds:[m.id],options:[{action:'评审前用四句话写清用户任务和困难',prediction:'可能减少对问题定义的反复确认，尚无实际结果。',cost:'准备约 15 分钟；如果问题材料不足，仍可能讨论不清楚。',metric:'评审后记录：哪些问题被澄清？是否出现反例？'},{action:'先找一位同事复述对方案的理解',prediction:'可能提前发现表达遗漏；不代表方案本身正确。',cost:'约 20 分钟；单人意见可能不代表用户。',metric:'记录对方复述与原意的差异，再比较正式讨论。'}]});
}

// 增量写入协议：只提交本次真实发生的改动，由服务端合并到最新版本。
// 这样多个页面、多个入口同时写入时不会互相覆盖，也不再依赖可能被边缘改写的 ETag。
const WORKSPACE_COLLECTIONS=['records','sources','skills','actions','feedback','reviews','events','profiles','documents'];
const LAB_COLLECTIONS=['models','observations','scenarios','states','experiments','configHistory'];
const MAX_OPS=300;
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);

// 对比上一次同步成功的快照与当前状态，生成最小操作集。只产生新增/修改，不产生删除。
function workspaceOps(prev,next,{limit=MAX_OPS}={}){
 if(!next||typeof next!=='object')throw Error('当前资料为空，无法生成保存操作。');
 const ops=[];
 for(const collection of WORKSPACE_COLLECTIONS){
  const before=new Map(((prev?.[collection])||[]).map(x=>[x.id,JSON.stringify(x)]));
  for(const item of (next[collection]||[])){
   if(!item||typeof item.id!=='string')throw Error('保存项缺少编号，已停止保存。');
   if(before.get(item.id)!==JSON.stringify(item))ops.push({collection,item});
  }
 }
 const prevLab=prev?.lab,nextLab=next?.lab;
 if(nextLab){
  for(const key of LAB_COLLECTIONS){
   const before=new Map(((prevLab?.[key])||[]).map(x=>[x.id,JSON.stringify(x)]));
   for(const item of (nextLab[key]||[])){
    if(!item||typeof item.id!=='string')throw Error('个人模型保存项缺少编号，已停止保存。');
    if(before.get(item.id)!==JSON.stringify(item))ops.push({collection:'lab.'+key,item});
   }
  }
  if(!same(prevLab?.config,nextLab.config))ops.push({collection:'lab.config',value:nextLab.config});
 }
 if(!same(prev?.coverage,next.coverage))ops.push({collection:'coverage',value:next.coverage});
 if(ops.length>limit)throw Error('本次修改了 '+ops.length+' 项，超过单次上限，请先导出当前资料再分批保存。');
 return ops;
}

// 服务端把操作合并到最新状态：同编号替换为本次提交的版本，新编号追加；不提供删除操作。
function applyWorkspaceOps(state,ops,{limit=MAX_OPS}={}){
 if(!state||typeof state!=='object')throw Error('云端资料格式不正确。');
 if(!Array.isArray(ops)||!ops.length)throw Error('没有需要保存的修改。');
 if(ops.length>limit)throw Error('单次保存的操作过多。');
 const merged=JSON.parse(JSON.stringify(state));
 for(const op of ops){
  if(!op||typeof op!=='object')throw Error('操作格式不正确。');
  const collection=op.collection;
  if(collection==='coverage'){
   if(!op.value||typeof op.value!=='object'||Array.isArray(op.value))throw Error('资料范围格式不正确。');
   merged.coverage=op.value;
   continue;
  }
  if(collection==='lab.config'){
   if(!merged.lab)throw Error('当前资料没有个人模型模块，无法保存规则。');
   merged.lab.config=op.value;
   continue;
  }
  const item=op.item;
  if(!item||typeof item.id!=='string'||!item.id)throw Error('保存项缺少编号。');
  let list;
  if(WORKSPACE_COLLECTIONS.includes(collection)){
   list=merged[collection];
  }else if(typeof collection==='string'&&collection.startsWith('lab.')){
   const key=collection.slice(4);
   if(!LAB_COLLECTIONS.includes(key))throw Error('未知的数据集合：'+collection);
   if(!merged.lab)throw Error('当前资料没有个人模型模块，无法保存该项。');
   list=merged.lab[key];
  }else{
   throw Error('未知的数据集合：'+String(collection));
  }
  if(!Array.isArray(list))throw Error('数据集合不存在：'+collection);
  const index=list.findIndex(x=>x&&x.id===item.id);
  if(index>=0)list[index]=item;else list.push(item);
 }
 return merged;
}

// 平台层：把工作台状态从「R2 上的一份 JSON」升级为「D1 逐条实体 + 版本流水」，
// 并补上独立登录、每日快照、定时复查提醒与健康检查。


const LEGACY_STATE_KEY='owner/digital-self-v2/workspace.json';
const COLLECTIONS=['records','sources','skills','actions','feedback','reviews','events','profiles','documents'];
const LAB_KEYS=['models','observations','scenarios','states','experiments','configHistory'];
const BACKUP_INDEX='owner/digital-self-v2/backups/index.json';
const MAX_BACKUPS=30;
const DDL=[
 "CREATE TABLE IF NOT EXISTS ds_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL)",
 "CREATE TABLE IF NOT EXISTS ds_entity(collection TEXT NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL,seq INTEGER NOT NULL,saved_at TEXT NOT NULL,PRIMARY KEY(collection,id))",
 "CREATE TABLE IF NOT EXISTS ds_history(rowid INTEGER PRIMARY KEY AUTOINCREMENT,collection TEXT NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL,saved_at TEXT NOT NULL)",
 "CREATE TABLE IF NOT EXISTS ds_session(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,expires_at TEXT NOT NULL)",
 "CREATE TABLE IF NOT EXISTS ds_notice(id TEXT PRIMARY KEY,kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT)",
 "CREATE TABLE IF NOT EXISTS ds_login(ip TEXT NOT NULL,at TEXT NOT NULL)",
 "CREATE INDEX IF NOT EXISTS ds_session_expiry ON ds_session(expires_at)"
];
const schemaReady=new WeakMap();
async function ensureSchema(db){
 const pending=schemaReady.get(db);
 if(pending)return pending;
 const promise=(async()=>{for(const sql of DDL)await db.prepare(sql).run();})();
 schemaReady.set(db,promise);
 try{await promise;}catch(error){schemaReady.delete(db);throw error;}
}
function nowISO(){return new Date().toISOString();}
function parse(text,fallback){try{return JSON.parse(text);}catch{return fallback;}}
// R2 不同绑定返回的对象能力不一致（有的只有 json()，有的只有 body），统一成文本。
async function bodyText(stored){
 if(!stored)return null;
 if(typeof stored.text==='function')return await stored.text();
 if(typeof stored.json==='function')return JSON.stringify(await stored.json());
 if(typeof stored.body==='string')return stored.body;
 if(stored.body instanceof Uint8Array)return new TextDecoder().decode(stored.body);
 return null;
}

// ---------- D1 存储 ----------
async function d1Load(db,env){
 await ensureSchema(db);await d1Init(db,env);
 const metaRows=await db.prepare('SELECT key,value FROM ds_meta').all();
 const meta={};for(const row of metaRows.results||[])meta[row.key]=row.value;
 if(meta.initialized!=='1')throw Error('个人资料尚未完成初始化。');
 const rows=await db.prepare('SELECT collection,id,body FROM ds_entity ORDER BY seq DESC').all();
 const state={schemaVersion:Number(meta.schemaVersion||2),revision:Number(meta.revision||0),updatedAt:meta.updatedAt||nowISO(),mode:meta.mode||'personal',
  coverage:meta.coverage?parse(meta.coverage,{}):{},profiles:[],records:[],sources:[],skills:[],actions:[],feedback:[],reviews:[],events:[],documents:[]};
 const lab={};
 for(const key of LAB_KEYS)lab[key]=[];
 for(const row of rows.results||[]){
  const item=parse(row.body,null);
  if(!item)continue;
  if(row.collection.startsWith('lab.')){const key=row.collection.slice(4);if(!LAB_KEYS.includes(key))continue;lab[key].push(item);}
  else if(state[row.collection])state[row.collection].push(item);
 }
 const hasLab=LAB_KEYS.some(key=>lab[key].length)||Boolean(meta.labConfig);
 if(hasLab){lab.schemaVersion=1;lab.config=meta.labConfig?parse(meta.labConfig,{minCases:2,targetObservations:5,reviewDays:7}):{minCases:2,targetObservations:5,reviewDays:7};state.lab=lab;}
 return {state,revision:state.revision,kind:'d1'};
}
function metaValueJSON(value){return typeof value==='string'?value:JSON.stringify(value);}
async function d1MetaSet(db,batch,key,value){batch.push(db.prepare('INSERT INTO ds_meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').bind(key,metaValueJSON(value)));}
async function d1Init(db,env){
 const row=await db.prepare("SELECT value FROM ds_meta WHERE key='schemaVersion'").first();
 if(row)return;
 const stored=await env.BUCKET?.get(LEGACY_STATE_KEY);
 const state=stored?parse(await bodyText(stored),null)||null:null;
 const batch=[];let seq=1000;
 await d1MetaSet(db,batch,'schemaVersion','2');
 await d1MetaSet(db,batch,'revision',String(state?.revision||1));
 await d1MetaSet(db,batch,'updatedAt',state?.updatedAt||nowISO());
 await d1MetaSet(db,batch,'mode',state?.mode||'personal');
 if(state?.coverage)await d1MetaSet(db,batch,'coverage',JSON.stringify(state.coverage));
 if(state?.lab?.config)await d1MetaSet(db,batch,'labConfig',JSON.stringify(state.lab.config));
 if(state)await d1MetaSet(db,batch,'initialized','1');
 for(const collection of COLLECTIONS){
  const list=Array.isArray(state?.[collection])?state[collection]:[];
  list.forEach((item,index)=>{if(!item||typeof item.id!=='string')return;seq+=1;batch.push(db.prepare('INSERT INTO ds_entity(collection,id,body,seq,saved_at) VALUES(?,?,?,?,?) ON CONFLICT(collection,id) DO NOTHING').bind(collection,item.id,JSON.stringify(item),list.length-index,nowISO()));});
 }
 if(state?.lab)for(const key of LAB_KEYS){
  const list=Array.isArray(state.lab[key])?state.lab[key]:[];
  list.forEach((item,index)=>{if(!item||typeof item.id!=='string')return;seq+=1;batch.push(db.prepare('INSERT INTO ds_entity(collection,id,body,seq,saved_at) VALUES(?,?,?,?,?) ON CONFLICT(collection,id) DO NOTHING').bind('lab.'+key,item.id,JSON.stringify(item),list.length-index,nowISO()));});
 }
 await d1MetaSet(db,batch,'seq',String(seq));
 if(state)batch.push(db.prepare("INSERT OR IGNORE INTO ds_notice(id,kind,title,body,created_at) VALUES(?,?,?,?,?)").bind('notice-migrated','system','数据已迁入逐条存储','原 JSON 文档已导入 D1，历史仍保留在 R2 快照中。',nowISO()));
 await db.batch(batch);
}
async function d1Apply(db,env,ops){
 await ensureSchema(db);await d1Init(db,env);
 const stateRow=await db.prepare("SELECT value FROM ds_meta WHERE key='initialized'").first();
 if(stateRow?.value!=='1')throw Error('个人空间尚未初始化，请先完成第一次保存。');
 if(!Array.isArray(ops)||!ops.length)throw Error('没有需要保存的修改。');
 if(ops.length>300)throw Error('单次保存的操作过多。');
 const seqRow=await db.prepare("SELECT value FROM ds_meta WHERE key='seq'").first();
 let seq=Number(seqRow?.value||1000);
 const now=nowISO(),batch=[];
 for(const op of ops){
  if(!op||typeof op!=='object')throw Error('操作格式不正确。');
  if(op.collection==='coverage'){await d1MetaSet(db,batch,'coverage',JSON.stringify(op.value));continue;}
  if(op.collection==='lab.config'){await d1MetaSet(db,batch,'labConfig',JSON.stringify(op.value));continue;}
  const item=op.item;
  if(!item||typeof item.id!=='string'||!item.id)throw Error('保存项缺少编号。');
  const collection=op.collection;
  const isLab=typeof collection==='string'&&collection.startsWith('lab.');
  if(!COLLECTIONS.includes(collection)&&!(isLab&&LAB_KEYS.includes(collection.slice(4))))throw Error('未知的数据集合：'+String(collection));
  seq+=1;
  batch.push(db.prepare('INSERT INTO ds_history(collection,id,body,saved_at) SELECT collection,id,body,? FROM ds_entity WHERE collection=? AND id=?').bind(now,collection,item.id));
  batch.push(db.prepare('INSERT INTO ds_entity(collection,id,body,seq,saved_at) VALUES(?,?,?,?,?) ON CONFLICT(collection,id) DO UPDATE SET body=excluded.body,saved_at=excluded.saved_at').bind(collection,item.id,JSON.stringify(item),seq,now));
 }
 batch.push(db.prepare("UPDATE ds_meta SET value=CAST(value AS INTEGER)+1 WHERE key='revision'").bind());
 batch.push(db.prepare("INSERT INTO ds_meta(key,value) VALUES('updatedAt',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(now));
 batch.push(db.prepare("INSERT INTO ds_meta(key,value) VALUES('seq',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(String(seq)));
 // D1/本地 SQLite 在并发写入时可能拒绝嵌套事务；重试会让后到的操作合并到新版本，而不是丢修改。
 for(let attempt=0;attempt<5;attempt++){
  try{await db.batch(batch);break;}
  catch(error){if(attempt===4)throw error;await new Promise(r=>setTimeout(r,10+attempt*20));}
 }
 const rev=await db.prepare("SELECT value FROM ds_meta WHERE key='revision'").first();
 return {revision:Number(rev?.value||1),ops:ops.length};
}
async function d1Replace(db,env,state){
 await ensureSchema(db);await d1Init(db,env);
 const batch=[],now=nowISO();let seq=1000;
 batch.push(db.prepare('DELETE FROM ds_entity').bind());
 for(const collection of COLLECTIONS){
  const list=Array.isArray(state?.[collection])?state[collection]:[];
  list.forEach((item,index)=>{if(!item||typeof item.id!=='string')return;seq+=1;batch.push(db.prepare('INSERT INTO ds_entity(collection,id,body,seq,saved_at) VALUES(?,?,?,?,?)').bind(collection,item.id,JSON.stringify(item),list.length-index,now));});
 }
 if(state?.lab)for(const key of LAB_KEYS){
  const list=Array.isArray(state.lab[key])?state.lab[key]:[];
  list.forEach((item,index)=>{if(!item||typeof item.id!=='string')return;seq+=1;batch.push(db.prepare('INSERT INTO ds_entity(collection,id,body,seq,saved_at) VALUES(?,?,?,?,?)').bind('lab.'+key,item.id,JSON.stringify(item),list.length-index,now));});
 }
 await d1MetaSet(db,batch,'schemaVersion',String(state?.schemaVersion||2));
 await d1MetaSet(db,batch,'revision',String(Number(state?.revision||1)));
 await d1MetaSet(db,batch,'updatedAt',now);
 await d1MetaSet(db,batch,'mode',state?.mode||'personal');
 await d1MetaSet(db,batch,'coverage',JSON.stringify(state?.coverage||{}));
 if(state?.lab?.config)await d1MetaSet(db,batch,'labConfig',JSON.stringify(state.lab.config));
 await d1MetaSet(db,batch,'seq',String(seq));
 await d1MetaSet(db,batch,'initialized','1');
 await db.batch(batch);
 return {revision:Number(state?.revision||1)};
}
async function d1Health(db){
 try{const r=await db.prepare('SELECT 1 AS ok').first();return Boolean(r?.ok);}catch{return false;}
}

// ---------- R2 整份文档（未绑定 D1 的旧站点仍可用） ----------
async function blobLoad(env){
 const stored=await env.BUCKET.get(LEGACY_STATE_KEY);
 if(!stored)throw Error('个人资料尚未完成初始化。');
 return {state:parse(await bodyText(stored),null),revision:0,kind:'blob',etag:stored.etag};
}
async function blobApply(env,ops){
 const stored=await env.BUCKET.get(LEGACY_STATE_KEY);
 if(!stored)throw Error('个人空间尚未初始化，请先完成第一次保存。');
 for(let attempt=0;attempt<5;attempt++){
  const current=attempt===0?stored:await env.BUCKET.get(LEGACY_STATE_KEY);
  if(!current)throw Error('个人空间尚未初始化，请先完成第一次保存。');
  const old=parse(await bodyText(current),null);
  const merged=applyWorkspaceOps(old,ops);
  merged.mode='personal';merged.revision=(old.revision||1)+1;merged.updatedAt=nowISO();
  const saved=await env.BUCKET.put(LEGACY_STATE_KEY,JSON.stringify(merged),{onlyIf:{etagMatches:current.etag},httpMetadata:{contentType:'application/json'}});
  if(saved)return {revision:merged.revision,ops:ops.length};
 }
 throw Error('检测到另一处正在写入，本次没有覆盖。你的修改仍保留在本页，可以稍后重试同步。');
}
async function blobReplace(env,state){
 const existing=env.BUCKET.head?await env.BUCKET.head(LEGACY_STATE_KEY):await env.BUCKET.get(LEGACY_STATE_KEY);
 if(existing)throw Error('个人资料已存在；初始化不会覆盖它。');
 const saved=await env.BUCKET.put(LEGACY_STATE_KEY,JSON.stringify(state),{onlyIf:{etagDoesNotMatch:'*'},httpMetadata:{contentType:'application/json'}});
 if(!saved)throw Error('资料已被另一个请求初始化。');
 return {revision:Number(state.revision||1)};
}

async function d1Touch(db,env){
 await ensureSchema(db);await d1Init(db,env);
 const now=nowISO();
 await db.batch([
  db.prepare("UPDATE ds_meta SET value=CAST(value AS INTEGER)+1 WHERE key='revision'").bind(),
  db.prepare("INSERT INTO ds_meta(key,value) VALUES('updatedAt',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(now)
 ]);
 const rev=await db.prepare("SELECT value FROM ds_meta WHERE key='revision'").first();
 return {revision:Number(rev?.value||1),ops:0};
}
async function blobTouch(env){
 const stored=await env.BUCKET.get(LEGACY_STATE_KEY);
 if(!stored){throw Error('个人资料尚未完成初始化。');}
 const state=parse(await bodyText(stored),null);
 state.revision=(Number(state.revision)||1)+1;state.updatedAt=nowISO();
 const saved=await env.BUCKET.put(LEGACY_STATE_KEY,JSON.stringify(state),{onlyIf:{etagMatches:stored.etag},httpMetadata:{contentType:'application/json'}});
 if(!saved)throw Error('检测到另一处正在写入，本次没有覆盖。请稍后重试同步。');
 return {revision:state.revision,ops:0};
}

async function createStore(env){
 if(env.DB){
  await ensureSchema(env.DB);
  return {kind:'d1',load:()=>d1Load(env.DB,env),apply:ops=>d1Apply(env.DB,env,ops),replace:state=>d1Replace(env.DB,env,state),touch:()=>d1Touch(env.DB,env),health:()=>d1Health(env.DB)};
 }
 return {kind:'blob',load:()=>blobLoad(env),apply:ops=>blobApply(env,ops),replace:state=>blobReplace(env,state),touch:()=>blobTouch(env),health:async()=>Boolean(env.BUCKET)};
}

// ---------- 备份 ----------
function stamp(){return nowISO().replace(/[:.]/g,'-');}
async function readBackupIndex(env){
 if(!env.BUCKET)return [];
 const stored=await env.BUCKET.get(BACKUP_INDEX);
 return stored?parse(await bodyText(stored),[])||[]:[];
}
async function snapshot(env,store,{reason='manual'}={}){
 if(!env.BUCKET)throw Error('备份存储尚未配置。');
 const {state}=await store.load();
 const at=nowISO(),key='owner/digital-self-v2/backups/state-'+stamp()+'.json';
 await env.BUCKET.put(key,JSON.stringify(state),{httpMetadata:{contentType:'application/json'}});
 const index=await readBackupIndex(env);
 index.unshift({key,at,reason,revision:state.revision||0});
 while(index.length>MAX_BACKUPS){const dropped=index.pop();try{await env.BUCKET.delete(dropped.key);}catch{}}
 await env.BUCKET.put(BACKUP_INDEX,JSON.stringify(index),{httpMetadata:{contentType:'application/json'}});
 if(env.DB)await env.DB.prepare("INSERT INTO ds_meta(key,value) VALUES('lastSnapshot',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(at).run();
 return {key,at,reason};
}
async function restoreSnapshot(env,store,key){
 if(!env.BUCKET)throw Error('备份存储尚未配置。');
 if(typeof key!=='string'||!key.startsWith('owner/digital-self-v2/backups/'))throw Error('备份编号不正确。');
 const stored=await env.BUCKET.get(key);
 if(!stored)throw Error('找不到这份备份。');
 const state=parse(await bodyText(stored),null);
 if(!state)throw Error('备份内容无法解析。');
 const result=await store.replace(state);
 return {...result,restored:key};
}

// ---------- 独立登录 ----------
const COOKIE='ds_session';
const SESSION_SECONDS=30*24*60*60;
function cookieValue(request,name){
 const raw=request.headers.get('Cookie')||'';
 for(const part of raw.split(';')){const [k,...rest]=part.trim().split('=');if(k===name)return rest.join('=');}
 return '';
}
async function hmac(env,text){
 const secret=env.SESSION_SECRET||env.SITE_ACCESS_CODE||'';
 const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);
 const sig=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(text));
 return [...new Uint8Array(sig)].map(b=>b.toString(16).padStart(2,'0')).join('');
}
function equal(a,b){if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let out=0;for(let i=0;i<a.length;i++)out|=a.charCodeAt(i)^b.charCodeAt(i);return out===0;}
function authEnabled(env){return Boolean(env.DB&&env.SITE_ACCESS_CODE);}
async function login(request,env,db,body){
 if(!authEnabled(env))throw Error('当前站点未启用独立登录。');
 const code=String(body?.code||'').trim();
 if(!code||code.length>200)return {status:400,message:'请输入访问口令。'};
 const ip=(request.headers.get('CF-Connecting-IP')||request.headers.get('X-Forwarded-For')||'unknown').split(',')[0].trim();
 const hourAgo=new Date(Date.now()-3600*1000).toISOString();
 const recent=await db.prepare('SELECT COUNT(*) AS n FROM ds_login WHERE ip=? AND at>?').bind(ip,hourAgo).first();
 if(Number(recent?.n||0)>=8)return {status:429,message:'尝试次数过多，请一小时后再试。'};
 if(!equal(code,env.SITE_ACCESS_CODE)){
  await db.prepare('INSERT INTO ds_login(ip,at) VALUES(?,?)').bind(ip,nowISO()).run();
  return {status:401,message:'访问口令不正确。'};
 }
 const id=crypto.randomUUID(),expires=new Date(Date.now()+SESSION_SECONDS*1000).toISOString();
 await db.prepare('INSERT INTO ds_session(id,created_at,expires_at) VALUES(?,?,?)').bind(id,nowISO(),expires).run();
 const sig=await hmac(env,id);
 const secure=String(request.url||'').startsWith('https://')||env.SITE_FORCE_SECURE==='1'?' Secure;':'';
 const cookie=`${COOKIE}=${id}.${sig}; Path=/; HttpOnly;${secure} SameSite=Lax; Max-Age=${SESSION_SECONDS}`;
 return {status:200,cookie,body:{ok:true,expires}};
}
async function logout(request,env,db){
 const value=cookieValue(request,COOKIE);const id=value.split('.')[0];
 if(id&&db)try{await db.prepare('DELETE FROM ds_session WHERE id=?').bind(id).run();}catch{}
 return `${COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`;
}
async function sessionOwner(request,env){
 if(!authEnabled(env))return false;
 const value=cookieValue(request,COOKIE);if(!value)return false;
 const [id,sig]=value.split('.');
 if(!id||!sig)return false;
 if(!equal(sig,await hmac(env,id)))return false;
 try{
  const row=await env.DB.prepare('SELECT expires_at FROM ds_session WHERE id=?').bind(id).first();
  if(!row)return false;
  if(Date.parse(row.expires_at)<Date.now()){await env.DB.prepare('DELETE FROM ds_session WHERE id=?').bind(id).run();return false;}
  return true;
 }catch{return false;}
}

// ---------- 定时任务：快照 + 复查提醒 ----------
async function runDaily(env,{now=new Date()}={}){
 const store=await createStore(env);
 const result={snapshot:null,notices:0,reminded:false};
 try{result.snapshot=(await snapshot(env,store,{reason:'cron'})).key;}catch(error){result.snapshotError=error.message;}
 let state=null;
 try{state=(await store.load()).state;}catch{}
 if(state){
  const days=(iso)=>{const d=Date.parse(iso);return Number.isFinite(d)?Math.floor((now.getTime()-d)/86400000):null;};
  const dueActions=(state.actions||[]).filter(a=>a.status==='active'&&days(a.createdAt)>=7).length;
  const staleRecords=(state.records||[]).filter(r=>r.review==='pending'&&days(r.createdAt)>=7).length;
  if(env.DB&&(dueActions||staleRecords)){
   const id='notice-'+now.toISOString().slice(0,10);
   const body=`${staleRecords} 条记录待整理；${dueActions} 个已采纳行动超过 7 天没有反馈。`;
   await env.DB.prepare('INSERT OR IGNORE INTO ds_notice(id,kind,title,body,created_at) VALUES(?,?,?,?,?)').bind(id,'review','该把结果带回来了',body,nowISO()).run();
   result.notices=1;
  }
  if(env.FEISHU_WEBHOOK_URL&&now.getUTCDay()===1){
   const text=`灵感一现 · 本周复查\n待整理记录：${staleRecords}\n超过 7 天未反馈行动：${dueActions}\n入口：${env.SITE_URL||'/'}`;
   try{await fetch(env.FEISHU_WEBHOOK_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({msg_type:'text',content:{text}})});result.reminded=true;}catch{}
  }
 }
 if(env.DB)await env.DB.prepare("INSERT INTO ds_meta(key,value) VALUES('lastCron',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(nowISO()).run().catch(()=>{});
 if(env.DB){try{await env.DB.prepare('DELETE FROM ds_session WHERE expires_at<?').bind(nowISO()).run();await env.DB.prepare('DELETE FROM ds_login WHERE at<?').bind(new Date(now.getTime()-7*86400000).toISOString()).run();}catch{}}
 return result;
}
async function platformHealth(env){
 const store=await createStore(env);
 const health={storage:{database:Boolean(env.DB),bucket:Boolean(env.BUCKET)},engine:store.kind,auth:authEnabled(env)};
 try{health.dbReady=await store.health();}catch{health.dbReady=false;}
 if(env.DB)try{
  const meta=await env.DB.prepare("SELECT key,value FROM ds_meta WHERE key IN ('revision','lastSnapshot','lastCron')").all();
  health.meta=Object.fromEntries((meta.results||[]).map(r=>[r.key,r.value]));
  const notices=await env.DB.prepare('SELECT COUNT(*) AS n FROM ds_notice WHERE read_at IS NULL').first();
  health.unreadNotices=Number(notices?.n||0);
 }catch{}
 return health;
}

const CAPTURE_TIMEZONE='Asia/Shanghai';
const CAPTURE_KINDS={task:'待办',idea:'观念',question:'问题',project:'目标与项目',learning:'学习线索'};
const CAPTURE_STATUSES={inbox:'待整理',ready:'待执行',doing:'进行中',waiting:'等待中',done:'已完成',cancelled:'已取消'};
const CAPTURE_AUTHORSHIP={user_original:'本人原创',ai_quote:'AI建议/转述',other_quote:'他人观点',unknown:'作者待确认'};
const PRINCIPLE_FIELDS=[['phenomenon','现象与原话'],['goal','想实现的目标'],['facts','已知事实'],['constraints','真实约束'],['assumptions','待验证假设'],['mechanisms','候选机制'],['alternatives','替代解释与反例'],['prediction','怎样区分这些解释'],['next_test','最小验证行动'],['applicability','适用边界与未知']];
function canonical(x){if(Array.isArray(x))return '['+x.map(canonical).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';return JSON.stringify(x);}
async function sha256(bytes){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',typeof bytes==='string'?new TextEncoder().encode(bytes):bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');}
function captureError(message,status=400){return Object.assign(new Error(message),{status});}
function check(v,msg){if(!v)throw captureError(msg);}
function identifier(v){return typeof v==='string'&&!['.','..'].includes(v)&&/^[a-zA-Z0-9._:-]{1,128}$/.test(v);}
function fileBytes(f){check(f&&['utf8','base64'].includes(f.encoding),'文件编码不正确。');if(f.encoding==='utf8'){check(typeof f.content==='string','文件正文不正确。');return new TextEncoder().encode(f.content);}try{return Uint8Array.from(atob(f.content),c=>c.charCodeAt(0));}catch{throw captureError('附件 Base64 编码不正确。');}}
async function makeCapturePacket({batchId,producer='manual',messages=[],analysis=[],attachments={},capturedAt=new Date().toISOString(),status='success'}){
 const files={'messages.jsonl':{encoding:'utf8',content:messages.map(x=>JSON.stringify(x)).join('\n')},'analysis.jsonl':{encoding:'utf8',content:analysis.map(x=>JSON.stringify(x)).join('\n')},...attachments};
 const manifest={schema_version:1,batch_id:batchId,producer,captured_at:capturedAt,status,files:[]};for(const [path,file] of Object.entries(files)){const bytes=fileBytes(file);manifest.files.push({path,sha256:await sha256(bytes),bytes:bytes.length});}return {manifest,files};
}
async function validateCapturePacket(packet){
 const m=packet?.manifest;check(m?.schema_version===1&&identifier(m.batch_id),'批次格式版本或编号不正确。');check(typeof m.producer==='string'&&m.producer.length<=80,'请提供采集来源。');check(['success','no_change'].includes(m.status),'只有成功采集或明确无新增的批次可以提交。');check(typeof m.captured_at==='string'&&Number.isFinite(Date.parse(m.captured_at)),'采集时间格式不正确。');check(Array.isArray(m.files)&&m.files.length>=2&&m.files.length<=32,'文件清单不正确。');
 const paths=new Set();let total=0;const decoded={};for(const entry of m.files){check(typeof entry.path==='string'&&(/^(messages|analysis)\.jsonl$/.test(entry.path)||/^attachments\/[a-zA-Z0-9._-]{1,180}$/.test(entry.path))&&!entry.path.split('/').some(p=>p==='.'||p==='..')&&!paths.has(entry.path),'附件路径不正确或重复。');paths.add(entry.path);const b=fileBytes(packet.files?.[entry.path]);total+=b.length;check(b.length<=4_000_000&&total<=8_000_000,'批次超过 8 MB 或单文件超过 4 MB，请拆分上传。');check(b.length===entry.bytes&&await sha256(b)===entry.sha256,'文件校验失败：'+entry.path);decoded[entry.path]=b;}
 check(paths.has('messages.jsonl')&&paths.has('analysis.jsonl'),'缺少原消息或分析文件。');check(Object.keys(packet.files||{}).every(k=>paths.has(k)),'存在未登记的文件。');
 const lines=name=>{try{return new TextDecoder('utf-8',{fatal:true}).decode(decoded[name]).split(/\r?\n/).filter(x=>x.trim()).map(x=>JSON.parse(x));}catch{throw captureError(name+'不是有效的 UTF-8 JSONL。');}};
 const messages=lines('messages.jsonl'),analysis=lines('analysis.jsonl');check(messages.length<=200&&analysis.length<=400,'单批最多 200 条消息、400 条拆分项。');const ids=new Set();for(const msg of messages){check(identifier(msg.id)&&!ids.has(msg.id),'原消息编号无效或重复。');ids.add(msg.id);check(typeof msg.text==='string'&&msg.text.length<=20000,'消息正文不正确。');check(msg.source_timestamp===null||typeof msg.source_timestamp==='string'&&Number.isFinite(Date.parse(msg.source_timestamp)),'消息原始时间不明时必须为 null。');check(Object.keys(CAPTURE_AUTHORSHIP).includes(msg.authorship),'消息作者性质不正确。');check(Array.isArray(msg.attachments||[])&&(msg.attachments||[]).every(p=>paths.has(p)&&p.startsWith('attachments/')),'消息附件引用不存在。');}
 const aiIds=new Set();for(const item of analysis){check(identifier(item.id)&&!aiIds.has(item.id),'拆分项编号无效或重复。');aiIds.add(item.id);check(Object.keys(CAPTURE_KINDS).includes(item.kind)&&['personal','business','knowledge','build'].includes(item.domain),'拆分项分类不正确。');check(typeof item.title==='string'&&item.title.trim()&&item.title.length<=160,'拆分项标题不正确。');check(Array.isArray(item.source_ids)&&item.source_ids.length>0&&item.source_ids.every(id=>ids.has(id)),'分析必须引用本批原消息。');if(item.due_at!=null)check(typeof item.due_at==='string'&&Number.isFinite(Date.parse(item.due_at))&&typeof item.deadline_quote==='string'&&item.deadline_quote.trim()&&messages.some(msg=>item.source_ids.includes(msg.id)&&msg.text.includes(item.deadline_quote)),'截止日期必须有原消息中的明确依据。');check(!item.status||item.status==='inbox','上传程序不能更改任务执行状态。');check(JSON.stringify(item).length<30000,'单条分析过长。');}
 check(m.status!=='no_change'||messages.length===0&&analysis.length===0,'无新增批次不应附带新记录。');return {manifest:m,messages,analysis,decoded,hash:await sha256(canonical(packet))};
}
function splitCaptureText(text){return String(text).split(/\n+/).map(x=>x.trim()).filter(Boolean).flatMap(line=>/^(to\s?do\s?list|待办)\s*[:：]/i.test(line)?line.replace(/^(to\s?do\s?list|待办)\s*[:：]/i,'').split(/[，,；;]/).map(x=>x.trim()).filter(Boolean):[line]);}
function classifyCapture(text){if(/^(问题|疑问)[:：]|[？?]$/.test(text))return 'question';if(/^(观念|观点|原则)[:：]/.test(text))return 'idea';if(/^(目标|规划|项目)[:：]|方向.*思考/.test(text))return 'project';if(/^(学习|研究|阅读)/.test(text))return 'learning';if(/^(待办|todo)[:：]|投递|修改|提交|新增|完成|^(整理|安排|联系|检查|确认|准备)/.test(text))return 'task';return 'idea';}
function validateCaptureEdit(input,current){
 const next={...current,...input};check(Object.keys(CAPTURE_STATUSES).includes(next.status),'任务状态不正确。');check(Object.keys(CAPTURE_KINDS).includes(next.kind),'记录类型不正确。');check(typeof next.title==='string'&&next.title.trim()&&next.title.length<=160,'请填写有效标题。');check(['pending','adopted','rejected'].includes(next.adoption_status),'观念确认状态不正确。');check(['unknown','actual','simulation'].includes(next.reality),'记录性质不正确。');check(['personal','business','knowledge','build'].includes(next.domain),'领域不正确。');
 for(const k of ['due_at','planned_at'])check(next[k]==null||typeof next[k]==='string'&&/T/.test(next[k])&&Number.isFinite(Date.parse(next[k])),'日期需包含时间和时区。');
 check(!next.principles||typeof next.principles==='object'&&!Array.isArray(next.principles)&&Object.entries(next.principles).every(([k,v])=>PRINCIPLE_FIELDS.some(f=>f[0]===k)&&typeof v==='string'&&v.length<=6000),'分析字段不正确。');
 if(next.outcome!=null)check(typeof next.outcome==='string'&&next.outcome.length<=6000,'行动结果过长。');
 // 关联只能指向仍然存在的记录；重复项在保存前合并，避免同一来源被重复计入。
 if(next.related_ids!=null){check(Array.isArray(next.related_ids),'关联字段不正确。');next.related_ids=[...new Set(next.related_ids.filter(x=>typeof x==='string'&&x.trim()).map(x=>x.trim().slice(0,150)))];check(next.related_ids.length<=20,'关联记录最多 20 条。');}
 // 数据质量：完成状态必须留下实际结果，否则“已完成”只是一句自我宣告。
 const outcomeText=typeof next.outcome==='string'?next.outcome.trim():'';
 if(next.status==='done')check(outcomeText.length>=4,'标记完成前请写下实际结果（至少 4 个字）。');
 // 记录性质从“未确认/模拟”升级为“真实发生”时，必须同时补上可回看的观察结果。
 if(next.reality==='actual'&&current.reality!=='actual')check(outcomeText.length>=8,'改记为真实发生前，请写下实际发生了什么（至少 8 个字）。');
 return next;
}
function captureICS(items,{alarmMinutes=30,calendarName='灵感一现 · 提醒'}={}){
 const esc=v=>String(v||'').replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');
 const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');
 const minutes=Number.isFinite(Number(alarmMinutes))?Math.min(1440,Math.max(0,Number(alarmMinutes))):30;
 const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//LingGanYiXian//Capture V4.1//ZH','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:'+esc(calendarName),'X-WR-TIMEZONE:Asia/Shanghai'];
 for(const item of items.filter(x=>x.kind==='task'&&x.due_at&&x.schedule_confirmed&&!['done','cancelled'].includes(x.status))){
  const start=new Date(item.due_at),end=new Date(start.valueOf()+30*60000);
  rows.push('BEGIN:VEVENT','UID:'+esc(item.id)+'@linggan','DTSTAMP:'+stamp(item.updated_at||new Date().toISOString()),'DTSTART:'+stamp(start),'DTEND:'+stamp(end),'SUMMARY:'+esc(item.title),'DESCRIPTION:'+esc((item.next_action||'请回知识库记录结果。')+(item.acceptance_criteria?'\n完成标准：'+item.acceptance_criteria:'')),'CATEGORIES:'+esc('灵感一现'),'X-LINGGAN-ITEM:'+esc(item.id),'END:VEVENT');
  if(minutes>0)rows.splice(rows.length-1,0,'BEGIN:VALARM','TRIGGER:-PT'+minutes+'M','ACTION:DISPLAY','DESCRIPTION:'+esc('待办提醒：'+item.title),'END:VALARM');
 }
 rows.push('END:VCALENDAR');return rows.join('\r\n')+'\r\n';
}


const capID=()=>crypto.randomUUID();
function capSafeParse(raw,fallback=null){try{return JSON.parse(raw);}catch{return fallback;}}
function capParse(row){
 if(!row)return null;const body=capSafeParse(row.body,{});
 return {...body,id:row.id,kind:body.kind||row.kind,domain:body.domain||row.domain,title:body.title||row.title||'（正文缺失）',status:row.status,due_at:row.due_at,revision:row.revision,created_at:row.created_at,updated_at:row.updated_at};
}
// 行级字段（id/状态/截止/版本）由表维护；写回正文时剔除，避免旧状态被二次固化。
function capStoreBody(item){const {id,revision,created_at,updated_at,original_analysis,...rest}=item;return JSON.stringify({...rest,original_analysis});}
async function capJSON(req,limit=12000000){const raw=await req.text();if(new TextEncoder().encode(raw).length>limit)throw captureError('导入数据超过上限。',413);try{return JSON.parse(raw);}catch{throw captureError('请提交有效的 JSON 数据。');}}
async function capCredential(req,env){const h=req.headers.get('Authorization')||'';if(!h.startsWith('Bearer wb4.'))return null;const token=h.slice(7);return await env.DB.prepare('SELECT id FROM capture_credentials WHERE hash = ? AND revoked_at IS NULL').bind(await sha256(token)).first();}
// 统一按上海时区取自然日，服务端与前端不再各自拼接时区偏移。
function capDay(at=new Date()){
 const day=new Intl.DateTimeFormat('en-CA',{timeZone:CAPTURE_TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(at);
 const start=new Date(day+'T00:00:00+08:00').toISOString();
 return {day,start,end:new Date(Date.parse(start)+86400000).toISOString()};
}
function capTerms(query){
 return [...new Set(String(query||'').toLowerCase().split(/[\s,，、;；]+/).map(x=>x.trim()).filter(Boolean))].slice(0,6).map(x=>x.slice(0,40));
}
function capFields(item,terms){
 const map={title:item.title,next_action:item.next_action,outcome:item.outcome,analysis:item.original_analysis?.summary,principles:Object.values(item.principles||{}).join(' ')};
 return Object.entries(map).filter(([,v])=>typeof v==='string'&&terms.some(t=>v.toLowerCase().includes(t))).map(([k])=>k);
}
function capSnippet(item,terms=[]){
 const parts=[item.outcome,item.next_action,item.original_analysis?.summary,item.acceptance_criteria,item.principles?.phenomenon,item.principles?.goal].filter(x=>typeof x==='string'&&x.trim());
 const text=parts.join(' · ').replace(/\s+/g,' ').trim();
 if(!text)return '';
 const hits=terms.map(t=>text.toLowerCase().indexOf(t)).filter(i=>i>=0).sort((a,b)=>a-b);
 const from=hits.length?Math.max(0,hits[0]-30):0;
 return (from?'…':'')+text.slice(from,from+160)+(text.length>from+160?'…':'');
}
async function capSelectIn(env,table,columns,ids){
 const out=new Map(),list=[...new Set(ids||[])].filter(x=>typeof x==='string'&&x);
 for(let i=0;i<list.length;i+=200){const chunk=list.slice(i,i+200);const rows=await env.DB.prepare('SELECT '+columns+' FROM '+table+' WHERE id IN ('+chunk.map(()=>'?').join(',')+')').bind(...chunk).all();for(const row of rows.results)out.set(row.id,row);}
 return out;
}
async function capState(env,key){
 const stored=await env.BUCKET.get(key);if(!stored)return {state:null,etag:null};
 let state=null;try{state=await stored.json();}catch{state=null;}
 return {state,etag:stored.etag};
}
// 关联可以指向随手记，也可以指向知识树里的记录；已存在的历史关联允许保留，新增的未知编号直接拒绝。
async function capAssertRelated(env,ids,current,workspace){
 const keep=new Set((current||[]).filter(x=>typeof x==='string'));
 const list=[...new Set((ids||[]).filter(x=>typeof x==='string'))];
 if(!list.length)return;
 const found=await capSelectIn(env,'capture_items','id',list);
 let missing=list.filter(id=>!found.has(id)&&!keep.has(id));
 if(missing.length&&workspace){
  try{const {state}=await workspace.load(),recordIds=new Set((state?.records||[]).map(r=>r?.id));missing=missing.filter(id=>!recordIds.has(id));}catch{}
 }
 if(missing.length)throw captureError('关联记录不存在：'+missing.slice(0,3).join('、')+'。请刷新后重新选择。');
}
function capScoreTokens(text){
 const value=String(text||'').toLowerCase(),latin=value.match(/[a-z0-9]{2,}/g)||[],cn=value.match(/[\u4e00-\u9fff]{2,}/g)||[];
 return [...new Set([...latin,...cn.flatMap(s=>[s,...Array.from({length:s.length-1},(_,i)=>s.slice(i,i+2))])])];
}
function capOverlap(a,b){const set=new Set(b);return a.filter(t=>set.has(t));}

async function ingestCapture(env,packet,credentialId=null){
 const v=await validateCapturePacket(packet),m=v.manifest;
 const existing=await env.DB.prepare('SELECT hash, receipt FROM capture_batches WHERE id = ?').bind(m.batch_id).first();
 if(existing){if(existing.hash!==v.hash)throw captureError('同一批次编号的内容已改变，请创建新批次。',409);return {...capSafeParse(existing.receipt,{}),duplicate:true};}
 const now=new Date().toISOString(),rawKey='capture/batches/'+m.batch_id+'/'+v.hash+'.json';
 const msgHashes=new Map();for(const msg of v.messages)msgHashes.set(msg.id,await sha256(canonical(msg)));
 // 批内一次查出已存在的原消息与拆分项，避免逐条往返。
 const knownMessages=await capSelectIn(env,'capture_messages','id,hash',[...msgHashes.keys()]);
 for(const [id,hash] of msgHashes)if(knownMessages.has(id)&&knownMessages.get(id).hash!==hash)throw captureError('原消息编号已有不同正文，请生成新版本编号。',409);
 const knownItems=await capSelectIn(env,'capture_items','id',v.analysis.map(a=>a.id));
 const items=[];
 for(const a of v.analysis){
  if(knownItems.has(a.id))continue;
  const source=v.messages.filter(msg=>a.source_ids.includes(msg.id));
  const authors=[...new Set(source.map(msg=>msg.authorship))];
  items.push({...a,original_analysis:structuredClone(a),batch_id:m.batch_id,authorship:authors.length===1?authors[0]:'unknown',adoption_status:'pending',evidence_status:'unverified',reality:'unknown',schedule_confirmed:false,source_ids:a.source_ids,next_action:typeof a.next_action==='string'?a.next_action:'',acceptance_criteria:typeof a.acceptance_criteria==='string'?a.acceptance_criteria:'',principles:Object.fromEntries(PRINCIPLE_FIELDS.filter(([k])=>typeof a.principles_draft?.[k]==='string').map(([k])=>[k,a.principles_draft[k].slice(0,6000)])),related_ids:[],status:'inbox',due_at:a.due_at?new Date(a.due_at).toISOString():null,planned_at:null});
 }
 await env.BUCKET.put(rawKey,JSON.stringify(packet),{httpMetadata:{contentType:'application/json'}});
 const receipt={batch_id:m.batch_id,status:'committed',received_at:now,captured_at:m.captured_at,messages:v.messages.length,items:items.length,existing_items:v.analysis.length-items.length,sha256:v.hash};
 const statements=[];
 for(const msg of v.messages)statements.push(env.DB.prepare('INSERT INTO capture_messages (id,hash,body,batch_id,created_at) VALUES (?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET hash = CASE WHEN capture_messages.hash = excluded.hash THEN capture_messages.hash ELSE NULL END').bind(msg.id,msgHashes.get(msg.id),JSON.stringify(msg),m.batch_id,now));
 for(const item of items)statements.push(env.DB.prepare('INSERT OR IGNORE INTO capture_items (id,message_ids,kind,domain,title,body,status,due_at,revision,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,1,?,?)').bind(item.id,JSON.stringify(item.source_ids),item.kind,item.domain,item.title,capStoreBody(item),'inbox',item.due_at,now,now));
 statements.push(env.DB.prepare('INSERT INTO capture_batches (id,hash,created_at,captured_at,count,producer,raw_key,receipt,credential_id) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET hash = CASE WHEN capture_batches.hash = excluded.hash THEN capture_batches.hash ELSE NULL END').bind(m.batch_id,v.hash,now,m.captured_at,v.messages.length,m.producer,rawKey,JSON.stringify(receipt),credentialId));
 try{await env.DB.batch(statements);}catch(error){if(/constraint|NOT NULL|UNIQUE/i.test(String(error)))throw captureError('并发导入冲突，原有资料没有被覆盖，请核对批次后重试。',409);throw error;}
 return receipt;
}

// 多词检索：所有词都需命中（AND），标题/下一步/结果命中加权排序，并返回命中字段与摘要。
async function listCapture(env,url){
 const limit=Math.min(100,Math.max(1,Number(url.searchParams.get('limit'))||30)),offset=Math.max(0,Number(url.searchParams.get('offset'))||0),params=[],where=[];
 for(const key of ['kind','domain','status'])if(url.searchParams.get(key)&&url.searchParams.get(key)!=='all'){where.push(key+' = ?');params.push(url.searchParams.get(key));}
 const bucket=url.searchParams.get('bucket');
 if(bucket==='inbox'){where.push("status = 'inbox'");}
 else if(bucket==='done'){where.push("status = 'done'");}
 else if(['today','overdue','unscheduled'].includes(bucket)){
  where.push("kind = 'task' AND status NOT IN ('done','cancelled')");
  if(bucket==='unscheduled')where.push('due_at IS NULL');
  else{const day=capDay();
   if(bucket==='overdue'){where.push("due_at < ? AND json_extract(body,'$.schedule_confirmed') = 1");params.push(day.start);}
   else{where.push("((due_at >= ? AND due_at < ? AND json_extract(body,'$.schedule_confirmed') = 1) OR (json_extract(body,'$.planned_at') >= ? AND json_extract(body,'$.planned_at') < ?))");params.push(day.start,day.end,day.start,day.end);}
  }
 }
 const terms=capTerms(url.searchParams.get('q'));
 for(const term of terms){where.push('(title LIKE ? OR body LIKE ?)');params.push('%'+term+'%','%'+term+'%');}
 if(url.searchParams.get('updated_after')){where.push('updated_at > ?');params.push(url.searchParams.get('updated_after'));}
 const condition=where.length?' WHERE '+where.join(' AND '):'';
 const scoreExpr=terms.map(()=>"(CASE WHEN title LIKE ? THEN 3 ELSE 0 END + CASE WHEN json_extract(body,'$.next_action') LIKE ? THEN 2 ELSE 0 END + CASE WHEN json_extract(body,'$.outcome') LIKE ? THEN 1 ELSE 0 END)").join(' + ');
 const scoreParams=[];for(const term of terms)scoreParams.push('%'+term+'%','%'+term+'%','%'+term+'%');
 const rowsSql='SELECT * FROM capture_items'+condition+' ORDER BY '+(terms.length?'('+scoreExpr+') DESC,':'')+'created_at DESC,id DESC LIMIT ? OFFSET ?';
 const [rows,count]=await Promise.all([
  env.DB.prepare(rowsSql).bind(...params,...scoreParams,limit,offset).all(),
  env.DB.prepare('SELECT COUNT(*) AS n FROM capture_items'+condition).bind(...params).first()
 ]);
 const items=rows.results.map(row=>{
  const item=capParse(row);
  if(terms.length)item.match={terms,fields:capFields(item,terms),snippet:capSnippet(item,terms)};
  return item;
 });
 return {items,total:count.n,offset,limit,next_offset:offset+items.length<count.n?offset+items.length:null,query:{terms}};
}

async function capStatus(env){
 const batches=await env.DB.prepare('SELECT id,created_at,captured_at,count,producer,receipt FROM capture_batches ORDER BY created_at DESC,id DESC LIMIT 20').all();
 const credentials=await env.DB.prepare('SELECT id,label,created_at,revoked_at FROM capture_credentials ORDER BY created_at DESC').all();
 const count=await env.DB.prepare('SELECT kind,COUNT(*) AS n FROM capture_items GROUP BY kind').all();
 return {batches:batches.results.map(b=>({...b,receipt:capSafeParse(b.receipt,{})})),credentials:credentials.results,counts:count.results,storage:'D1 rows + R2 immutable batches',pushEnabled:Boolean(env.CAPTURE_GATEWAY_TOKEN),chatgptReader:'site_mcp',notificationDelivery:'calendar_export_only',timezone:CAPTURE_TIMEZONE};
}

async function capItem(env,id){
 const row=await env.DB.prepare('SELECT * FROM capture_items WHERE id = ?').bind(id).first();
 if(!row)throw captureError('找不到这条随手记。',404);
 const item=capParse(row),sourceIds=[...new Set((item.source_ids||[]).filter(x=>typeof x==='string'))];
 const [messages,history]=await Promise.all([
  sourceIds.length?env.DB.prepare('SELECT id,body FROM capture_messages WHERE id IN ('+sourceIds.map(()=>'?').join(',')+')').bind(...sourceIds).all():{results:[]},
  env.DB.prepare('SELECT revision,body,created_at FROM capture_versions WHERE item_id = ? ORDER BY revision DESC').bind(id).all()
 ]);
 const byId=new Map(messages.results.map(m=>[m.id,capSafeParse(m.body,m.body)])),
  sources=sourceIds.map(sid=>byId.get(sid)).filter(Boolean);
 return {item,sources,versions:history.results.map(h=>({...h,body:capSafeParse(h.body,h.body)}))};
}

async function capUpdate(env,id,input,match,workspace){
 if(match==null||match==='')throw captureError('请先读取当前版本，再保存修改。',428);
 const current=(await capItem(env,id)).item;
 if(String(current.revision)!==String(match))throw captureError('记录已被其他页面修改，请重新打开后合并。',409);
 const allowed=['title','kind','domain','status','due_at','planned_at','schedule_confirmed','next_action','acceptance_criteria','adoption_status','reality','principles','related_ids','outcome'];
 if(Object.keys(input||{}).some(k=>!allowed.includes(k)))throw captureError('修改中包含不能改写的来源字段。');
 const next=validateCaptureEdit(input,current);
 await capAssertRelated(env,next.related_ids,current.related_ids,workspace);
 const now=new Date().toISOString();next.updated_at=now;next.revision=current.revision+1;
 if(next.kind!=='task')next.schedule_confirmed=false;
 next.schedule_confirmed=Boolean(next.schedule_confirmed&&next.due_at);
 const result=await env.DB.batch([
  env.DB.prepare('INSERT INTO capture_versions (id,item_id,revision,body,created_at) SELECT ?,id,revision,body,? FROM capture_items WHERE id = ? AND revision = ? ON CONFLICT(item_id,revision) DO NOTHING').bind(capID(),now,id,current.revision),
  env.DB.prepare('UPDATE capture_items SET kind=?,domain=?,title=?,body=?,status=?,due_at=?,revision=revision+1,updated_at=? WHERE id=? AND revision=?').bind(next.kind,next.domain,next.title,capStoreBody(next),next.status,next.due_at,now,id,current.revision)
 ]);
 if(!result[1].meta.changes)throw captureError('并发修改，本次未覆盖。',409);
 return next;
}

// 相关候选由服务端计算：近 120 条内按标题与正文词重合排序，供本人确认而不是自动写入。
async function captureRelated(env,id){
 const current=(await capItem(env,id)).item;
 const rows=await env.DB.prepare('SELECT * FROM capture_items WHERE id <> ? ORDER BY updated_at DESC,id DESC LIMIT 120').bind(id).all();
 const sourceText=[current.title,current.next_action,current.outcome,current.original_analysis?.summary,...Object.values(current.principles||{})].filter(Boolean).join(' ');
 const sourceTokens=capScoreTokens(sourceText);
 const scored=rows.results.map(capParse).map(item=>{
  const text=[item.title,item.next_action,item.outcome,item.original_analysis?.summary].filter(Boolean).join(' ');
  const shared=capOverlap(sourceTokens,capScoreTokens(text));
  const score=shared.reduce((n,t)=>n+(item.title.toLowerCase().includes(t)?2:1),0)+(item.domain===current.domain?2:0)+(item.kind===current.kind?1:0);
  return {item,shared,score};
 }).filter(row=>row.shared.length&&row.score>=2).sort((a,b)=>b.score-a.score).slice(0,5);
 return {id,items:scored.map(({item,shared,score})=>({id:item.id,title:item.title,kind:item.kind,domain:item.domain,status:item.status,updated_at:item.updated_at,shared:shared.slice(0,6),score,snippet:capSnippet(item,shared.slice(0,3))})),note:'候选关联由关键词重合计算，只是提示，不代表因果或同一件事。'};
}

// 任务完成后显式沉淀：写入知识树的确定性记录 ID，重试不会产生重复条目。
async function promoteCapture(env,id,input,match,helpers){
 const current=(await capItem(env,id)).item;
 if(match!=null&&match!==''&&String(current.revision)!==String(match))throw captureError('记录已被其他页面修改，请刷新后再沉淀。',409);
 if(current.kind!=='task')throw captureError('只有待办/任务可以沉淀为实践经验。');
 if(current.status!=='done')throw captureError('请先把这条任务标记为已完成。');
 const outcome=String(input?.outcome??current.outcome??'').trim();
 if(outcome.length<4)throw captureError('请先写下实际结果（至少 4 个字），再沉淀为经验。');
 const workspace=helpers.workspace;
 let state;try{state=(await workspace.load()).state;}catch{state=null;}
 if(!state||!Array.isArray(state.records))throw captureError('个人空间尚未初始化，暂时无法沉淀到知识树。',409);
 const now=new Date().toISOString(),recordId='memory-capture-'+id;
 let created=false;
 if(!state.records.some(r=>r?.id===recordId)){
  const record={id:recordId,title:(String(input?.title||current.title).trim()||current.title).slice(0,120),summary:outcome.slice(0,280),original:'随手记任务：'+current.title+'\n下一步：'+(current.next_action||'未填写')+'\n实际结果：'+outcome+'\n完成标准：'+(current.acceptance_criteria||'未填写'),type:'experience',domain:current.domain,tags:[],date:now.slice(0,10),createdAt:now,origin:'capture-sediment',reality:'actual',provenance:'user_report',confidence:'medium',review:'pending',status:'active',related:(current.related_ids||[]).slice(0,5),sourceRefs:[{kind:'capture_item',id,label:'随手记：'+current.title,date:now}],questions:['还有哪些因素可能影响了这次结果？'],note:'来自随手记的实际结果，属于本人自述，尚未独立核验。'};
  const event={id:capID(),date:now,type:'capture-sediment',title:'把一条已完成任务沉淀为经验',recordId};
  try{await workspace.apply([{collection:'records',item:record},{collection:'events',item:event}]);}
  catch(error){throw captureError('知识树刚被另一处更新，请刷新后重试沉淀。',409);}
  created=true;
 }
 const next={...current,promoted_record_id:recordId,promoted_at:now,revision:current.revision+1,updated_at:now};
 const written=await env.DB.prepare('UPDATE capture_items SET body=?,revision=revision+1,updated_at=? WHERE id=? AND revision=?').bind(capStoreBody(next),now,id,current.revision).run();
 if(!written.meta.changes&&created)throw captureError('记录刚被修改，经验已写入但标记未更新，请刷新后重试。',409);
 return {status:created?'promoted':'exists',record_id:recordId,revision:current.revision+1};
}

async function reviewPack(env,url){
 const days=Math.min(90,Math.max(1,Number(url.searchParams.get('days'))||7)),now=Date.now();
 const from=new Date(now-(days-1)*86400000).toISOString(),rows=await env.DB.prepare('SELECT * FROM capture_items').all();
 const items=rows.results.map(capParse),recent=items.filter(x=>String(x.updated_at||x.created_at||'')>=from);
 const open=items.filter(x=>x.kind==='task'&&!['done','cancelled'].includes(x.status));
 const done=recent.filter(x=>x.kind==='task'&&x.status==='done');
 const overdue=open.filter(x=>x.due_at&&x.schedule_confirmed&&Date.parse(x.due_at)<now);
 const inbox=items.filter(x=>x.status==='inbox');
 const ideas=items.filter(x=>x.kind==='idea'&&x.adoption_status==='pending');
 const gaps=[...new Map(done.filter(x=>!String(x.outcome||'').trim()).concat(items.filter(x=>x.reality==='actual'&&!String(x.outcome||'').trim())).map(x=>[x.id,x])).values()];
 const oldestInbox=inbox.length?Math.floor((now-Math.min(...inbox.map(x=>Date.parse(x.created_at))))/86400000):0;
 const counts={items:items.length,recent:recent.length,inbox:inbox.length,tasks_open:open.length,done_in_range:done.length,overdue:overdue.length,ideas_pending:ideas.length,evidence_gaps:gaps.length};
 const brief=done.slice(0,12).map(x=>'- '+x.title+'：'+(String(x.outcome||'').trim().slice(0,120)||'（未记录实际结果）')).join('\n')||'- 本期没有标记完成的任务；这不等同于没有推进。';
 const late=overdue.slice(0,12).map(x=>'- '+x.title+'（原定 '+new Date(x.due_at).toLocaleString('zh-CN',{timeZone:CAPTURE_TIMEZONE})+'）').join('\n')||'- 没有已确认截止且逾期的任务。';
 const markdown=['# 灵感一现 · 近 '+days+' 天复盘包','','生成时间：'+new Date(now).toISOString()+'（'+CAPTURE_TIMEZONE+'）','',
  '## 数据概览','',Object.entries(counts).map(([k,v])=>'- '+k+'：'+v).join('\n'),'',
  '## 本期实际完成与结果','',brief,'',
  '## 逾期（已确认截止）','',late,'',
  '## 收件箱待整理','',inbox.length?'- 共 '+inbox.length+' 条，最早一条等待 '+oldestInbox+' 天。':'无','',
  '## 需要本人判断的观念','',ideas.length?ideas.slice(0,10).map(x=>'- '+x.title).join('\n'):'无','',
  '## 证据缺口','',gaps.length?gaps.slice(0,10).map(x=>'- '+x.title+'：缺少实际结果').join('\n'):'无','',
  '## 下周可以问自己的三个问题','','1. 哪一条完成的任务，实际结果与预期不同？','2. 哪一条待整理记录反复出现，值得先处理？','3. 哪一条观念需要一条反例来检验？','',
  '> 本复盘包只汇总已有记录，不做人格判断、因果推断或自动计划。'].join('\n');
 return {range:{days,from,to:new Date(now).toISOString()},counts,highlight:{done:done.slice(0,12).map(x=>({id:x.id,title:x.title,outcome:x.outcome||'',acceptance_criteria:x.acceptance_criteria||''})),overdue:overdue.slice(0,12).map(x=>({id:x.id,title:x.title,due_at:x.due_at})),inbox:inbox.slice(0,12).map(x=>({id:x.id,title:x.title,created_at:x.created_at})),ideas:ideas.slice(0,12).map(x=>({id:x.id,title:x.title}))},oldest_inbox_days:oldestInbox,markdown};
}

async function captureToday(env){
 const today=await listCapture(env,new URL('https://local/api/capture/items?bucket=today&limit=20')),
  overdue=await listCapture(env,new URL('https://local/api/capture/items?bucket=overdue&limit=20')),
  unscheduled=await listCapture(env,new URL('https://local/api/capture/items?bucket=unscheduled&limit=20'));
 return {day:capDay().day,today:today.items,overdue:overdue.items,unscheduled:unscheduled.items,counts:{today:today.total,overdue:overdue.total,unscheduled:unscheduled.total},note:'只读取已确认或已计划的待办；未排期不等于今天要做。'};
}

async function captureRoutes(req,env,helpers){
 const {json,userIdentity,serviceAuthorized}=helpers,url=new URL(req.url),path=url.pathname;
 if(!path.startsWith('/api/capture')&&!path.startsWith('/api/imports')&&path!=='/api/portable'&&path!=='/mcp')return null;
 try{
  const owner=userIdentity(req,env).owner,service=serviceAuthorized(req,env);
  if(path==='/mcp'){
   if(req.method!=='POST')return json({message:'仅支持 MCP POST。'},405);
   const rpc=await capJSON(req,10000);
   const tools=[
    {name:'capture_sync_status',description:'读取灵感一现私人随手记的最新导入回执与数据更新时间。',inputSchema:{type:'object',properties:{},additionalProperties:false}},
    {name:'capture_search',description:'检索随手记、待办和观念，返回来源性质；不会把AI分析当作本人已确认事实。多个词用空格分隔。',inputSchema:{type:'object',properties:{query:{type:'string'},updated_after:{type:'string'},offset:{type:'integer',minimum:0},kind:{type:'string'},domain:{type:'string'},status:{type:'string'},bucket:{type:'string'},limit:{type:'integer',minimum:1,maximum:100}},additionalProperties:false}},
    {name:'capture_read',description:'读取一条私人随手记及原消息、分析与历史版本。',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false}},
    {name:'capture_today',description:'读取今天的计划、已逾期的已确认待办和待排期任务。',inputSchema:{type:'object',properties:{},additionalProperties:false}},
    {name:'capture_review_pack',description:'生成近 N 天复盘包：完成与结果、逾期、待整理、待判断观念与证据缺口，含 Markdown。',inputSchema:{type:'object',properties:{days:{type:'integer',minimum:1,maximum:90}},additionalProperties:false}}
   ];
   let result;
   if(rpc.method==='server/discover')result={supportedVersions:['2026-07-28'],capabilities:{tools:{}}};
   else if(rpc.method==='initialize')result={protocolVersion:'2025-03-26',capabilities:{tools:{}},serverInfo:{name:'linggan-capture',version:'4.1.0'}};
   else if(rpc.method==='tools/list')result={tools};
   else if(rpc.method?.startsWith('notifications/'))return new Response(null,{status:202});
   else if(rpc.method==='tools/call'){
    if(!owner&&!service)return json({jsonrpc:'2.0',id:rpc.id,error:{code:-32001,message:'需要知识库所有者身份。'}},401);
    if(!env.DB)throw captureError('随手记数据库尚未配置。',503);
    const args=rpc.params?.arguments||{},name=rpc.params?.name;let value;
    if(name==='capture_sync_status')value=await capStatus(env);
    else if(name==='capture_read')value=await capItem(env,args.id);
    else if(name==='capture_today')value=await captureToday(env);
    else if(name==='capture_review_pack'){const u=new URL(url.origin+'/api/capture/review-pack');if(args.days)u.searchParams.set('days',String(args.days));value=await reviewPack(env,u);}
    else if(name==='capture_search'){
     const u=new URL(url.origin+'/api/capture/items');u.searchParams.set('q',String(args.query||''));
     if(args.updated_after)u.searchParams.set('updated_after',args.updated_after);
     for(const key of ['kind','domain','status','bucket'])if(args[key])u.searchParams.set(key,String(args[key]));
     u.searchParams.set('offset',String(args.offset||0));
     if(args.limit)u.searchParams.set('limit',String(args.limit));
     value=await listCapture(env,u);
    }else throw captureError('未知工具。',404);
    result={content:[{type:'text',text:JSON.stringify(value)}]};
   }else return json({jsonrpc:'2.0',id:rpc.id,error:{code:-32601,message:'未知方法。'}});
   return json({jsonrpc:'2.0',id:rpc.id??null,result});
  }
  if(!env.DB||!env.BUCKET)throw captureError('随手记数据库或附件存储尚未配置。',503);
  const upload=await capCredential(req,env);
  if(path==='/api/imports'&&req.method==='POST'){
   if(!owner&&!service&&!upload)return json({message:'需要所有者身份或专用上传凭证。'},401);
   if(owner&&!service&&!upload&&req.headers.get('Origin')!==url.origin)return json({message:'请求来源不一致。'},403);
   return json(await ingestCapture(env,await capJSON(req),upload?.id||null),201);
  }
  if(path.startsWith('/api/imports/')&&req.method==='GET'){
   if(!owner&&!service&&!upload)return json({message:'需要上传权限。'},401);
   const id=decodeURIComponent(path.slice('/api/imports/'.length));
   const r=await env.DB.prepare('SELECT receipt,credential_id FROM capture_batches WHERE id = ?').bind(id).first();
   if(upload&&r&&r.credential_id!==upload.id)return json({message:'只能读取本连接上传的批次回执。'},403);
   return r?json(capSafeParse(r.receipt,{})):json({message:'尚未收到此批次。'},404);
  }
  if(!owner&&!service)return json({message:'当前凭证不能读取或修改私人知识库。'},401);
  if(!['GET','HEAD'].includes(req.method)&&!service&&req.headers.get('Origin')!==url.origin)return json({message:'请求来源不一致。'},403);
  if(path==='/api/capture/status'&&req.method==='GET')return json(await capStatus(env));
  if(path==='/api/capture/review-pack'&&req.method==='GET')return json(await reviewPack(env,url));
  if(path==='/api/capture/items'&&req.method==='GET')return json(await listCapture(env,url));
  if(path.startsWith('/api/capture/items/')&&path.endsWith('/related')&&req.method==='GET'){
   const id=decodeURIComponent(path.slice('/api/capture/items/'.length,-'/related'.length));
   return json(await captureRelated(env,id));
  }
  if(path.startsWith('/api/capture/items/')&&path.endsWith('/promote')&&req.method==='POST'){
   const id=decodeURIComponent(path.slice('/api/capture/items/'.length,-'/promote'.length));
   const result=await promoteCapture(env,id,await capJSON(req,100000),req.headers.get('If-Match'),helpers);
   return json(result,result.status==='promoted'?201:200);
  }
  if(path.startsWith('/api/capture/items/')){
   const id=decodeURIComponent(path.slice('/api/capture/items/'.length));
   if(req.method==='GET')return json(await capItem(env,id));
   if(req.method==='PATCH')return json(await capUpdate(env,id,await capJSON(req,100000),req.headers.get('If-Match'),helpers.workspace));
  }
  if(path==='/api/capture/credentials'&&req.method==='POST'){
   const count=await env.DB.prepare('SELECT COUNT(*) AS n FROM capture_credentials WHERE revoked_at IS NULL').first();
   if(count.n>=5)throw captureError('已有5个有效连接，请先撤销不用的凭证。');
   const token='wb4.'+capID()+capID(),id=capID();
   await env.DB.prepare('INSERT INTO capture_credentials (id,hash,label,created_at) VALUES (?,?,?,?)').bind(id,await sha256(token),'WorkBuddy 上传',new Date().toISOString()).run();
   return json({credential_id:id,site_url:url.origin,token,site_access_token:env.CAPTURE_GATEWAY_TOKEN||null,scope:['imports:append','imports:receipt'],schema_version:1},201);
  }
  if(path.startsWith('/api/capture/credentials/')&&req.method==='DELETE'){
   await env.DB.prepare('UPDATE capture_credentials SET revoked_at=? WHERE id=?').bind(new Date().toISOString(),decodeURIComponent(path.split('/').at(-1))).run();
   return json({status:'revoked'});
  }
  if(path.startsWith('/api/capture/files/')&&req.method==='GET'){
   const batch=decodeURIComponent(path.split('/')[4]||''),file=url.searchParams.get('path');
   const row=await env.DB.prepare('SELECT raw_key FROM capture_batches WHERE id = ?').bind(batch).first();
   if(!row)throw captureError('找不到附件批次。',404);
   const obj=await env.BUCKET.get(row.raw_key),packet=await obj.json(),f=packet.files?.[file];
   if(!f||!file.startsWith('attachments/'))throw captureError('附件不存在。',404);
   const bytes=fileBytes(f);
   return new Response(bytes,{headers:{'Content-Type':/\.png$/i.test(file)?'image/png':/\.jpe?g$/i.test(file)?'image/jpeg':'application/octet-stream','Content-Disposition':'attachment; filename="'+file.split('/').at(-1)+'"','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
  }
  if(path==='/api/portable'&&req.method==='GET')return await portableCapture(env,helpers,url);
  return json({message:'没有此随手记接口。'},404);
 }catch(error){if(error.status)return json({message:error.message},error.status);console.error('capture_request_failed',error.name);return json({message:'随手记操作失败；旧数据没有被覆盖。'},500);}
}

function zipCapture(files){
 const encoder=new TextEncoder(),chunks=[],central=[];let offset=0;
 let crcTable=zipCapture.table;
 if(!crcTable){crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});zipCapture.table=crcTable;}
 const crc=b=>{let c=0xffffffff;for(const v of b)c=crcTable[(c^v)&255]^(c>>>8);return (c^0xffffffff)>>>0;};
 for(const [name,content] of Object.entries(files)){
  const n=encoder.encode(name),b=typeof content==='string'?encoder.encode(content):content,c=crc(b),head=new Uint8Array(30+n.length),v=new DataView(head.buffer);
  v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,c,true);v.setUint32(18,b.length,true);v.setUint32(22,b.length,true);v.setUint16(26,n.length,true);head.set(n,30);
  chunks.push(head,b);
  const cent=new Uint8Array(46+n.length),cv=new DataView(cent.buffer);
  cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,33,true);cv.setUint32(16,c,true);cv.setUint32(20,b.length,true);cv.setUint32(24,b.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);cent.set(n,46);
  central.push(cent);offset+=head.length+b.length;
 }
 const size=central.reduce((n,x)=>n+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);
 ev.setUint32(0,0x06054b50,true);ev.setUint16(8,central.length,true);ev.setUint16(10,central.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);
 const result=new Uint8Array(offset+size+22);let pos=0;for(const c of [...chunks,...central,end]){result.set(c,pos);pos+=c.length;}return result;
}

async function portableCapture(env,helpers,url){
 const now=new Date().toISOString(),params=url?url.searchParams:new URLSearchParams();
 const scope=String(params.get('scope')||'all').toLowerCase();
 if(!['all','capture','workspace','learning'].includes(scope))throw captureError('导出范围不正确：可选 all、capture、workspace、learning。');
 const sinceRaw=params.get('since');let since=null;
 if(sinceRaw){const at=Date.parse(sinceRaw);if(!Number.isFinite(at))throw captureError('since 需要是 ISO 日期或时间。');since=new Date(at).toISOString();}
 const wantCapture=scope==='all'||scope==='capture',wantWorkspace=scope==='all'||scope==='workspace',wantLearning=scope==='all'||scope==='learning';
 const LIMIT=48000000,MAX_FILES=20000,files={};let size=0,fileCount=0;
 const add=(path,content)=>{const bytes=typeof content==='string'?new TextEncoder().encode(content):content;size+=bytes.length;fileCount+=1;if(size>LIMIT||fileCount>MAX_FILES)throw captureError('导出超过本版 48MB 上限；请使用 scope=capture|workspace|learning，或加 since=日期 分批导出。',413);files[path]=content;return bytes;};
 let tables={};
 if(wantCapture){
  const names=['capture_batches','capture_messages','capture_items','capture_versions'];
  const rows=await env.DB.batch(names.map(t=>env.DB.prepare('SELECT * FROM '+t)));
  tables=Object.fromEntries(names.map((t,i)=>[t,rows[i].results.map(row=>{const copy={...row};delete copy.credential_id;return copy;})]));
  if(since)for(const t of names)tables[t]=tables[t].filter(row=>String(row.updated_at||row.created_at||'')>=since);
  add('data/capture-tables.json',JSON.stringify(tables,null,2));
 }
 let legacy=null,learn=null;
 if(wantWorkspace){try{legacy=(await helpers.workspace.load()).state;}catch{legacy=null;}add('data/workspace.json',JSON.stringify(legacy,null,2));}
 if(wantLearning){
  const stored=await env.BUCKET.get(helpers.LEARNING_KEY);
  learn=stored?await stored.json():capSafeParse(new TextDecoder().decode(Uint8Array.from(atob(ASSETS['/learning/records.json'].body),c=>c.charCodeAt(0))),{});
  add('data/learning.json',JSON.stringify(learn,null,2));
 }
 const records=[...(wantWorkspace?legacy?.records||[]:[]),...(wantCapture?tables.capture_items.map(capParse):[])];
 const escape=helpers.escapeHTML;let page='<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>灵感一现 · 离线阅读</title><style>body{max-width:960px;margin:40px auto;padding:20px;background:#f5f6ef;color:#344c3b;font:16px/1.8 system-ui}summary{cursor:pointer;font-weight:600}details{padding:18px;margin:12px 0;background:white;border-radius:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere}small{color:#687967}</style><h1>灵感一现 · 离线阅读</h1><p>导出时间 '+escape(now)+'。范围：'+escape(scope)+(since?' · 自 '+escape(since):'')+'。本页面无需登录或联网；这是阅读快照，修改不自动同步云端。</p>';
 for(const [i,r] of records.entries()){const content=r.original||r.summary||r.next_action||'',md='# '+r.title+'\n\n'+content+'\n\n来源与字段：\n\n```json\n'+JSON.stringify(r,null,2)+'\n```\n';add('wiki/'+String(i+1).padStart(5,'0')+'.md',md);page+='<details><summary>'+escape(r.title)+'</summary><pre>'+escape(md)+'</pre></details>';}
 if(learn){page+='<h2>经验学习和沉淀</h2>';for(const article of learn.articles||[])page+='<details><summary>'+escape(article.title)+'</summary><pre>'+escape(JSON.stringify(article,null,2))+'</pre></details>';}
 if(legacy){page+='<h2>来源账本</h2>';for(const source of legacy.sources||[])page+='<details><summary>'+escape(source.title)+'</summary><pre>'+escape(source.content||'')+'</pre></details>';}
 if(wantCapture)for(const batch of tables.capture_batches){const obj=await env.BUCKET.get(batch.raw_key);if(!obj)throw captureError('备份中缺少已提交批次，请稍后重试。',503);const packet=await obj.json();add('raw/'+batch.id+'/manifest.json',JSON.stringify(packet.manifest,null,2));for(const [path,file] of Object.entries(packet.files))add('raw/'+batch.id+'/'+path,fileBytes(file));}
 add('index.html',page);
 add('restore_sqlite.py',"import json,pathlib,sqlite3\nroot=pathlib.Path(__file__).resolve().parent\ndb=sqlite3.connect(root/'knowledge.sqlite')\ndb.execute('CREATE TABLE IF NOT EXISTS archive(collection TEXT,id TEXT,body TEXT,PRIMARY KEY(collection,id))')\ndef load(name):\n p=root/name\n return json.loads(p.read_text(encoding='utf-8')) if p.exists() else None\ntables=load('data/capture-tables.json') or {}\nlegacy=load('data/workspace.json') or {}\nlearning=load('data/learning.json') or {}\ncollections=list(tables.items())+[(k,v) for k,v in legacy.items() if isinstance(v,list)]+[('learning_articles',learning.get('articles',[])),('learning_methods',learning.get('methods',[]))]\nfor collection,rows in collections:\n for i,row in enumerate(rows):\n  db.execute('INSERT OR REPLACE INTO archive VALUES(?,?,?)',(collection,str(row.get('id',i)),json.dumps(row,ensure_ascii=False)))\nif legacy: db.execute('INSERT OR REPLACE INTO archive VALUES(?,?,?)',('workspace','complete',json.dumps(legacy,ensure_ascii=False)))\nif learning: db.execute('INSERT OR REPLACE INTO archive VALUES(?,?,?)',('learning','complete',json.dumps(learning,ensure_ascii=False)))\ndb.commit()\nprint(root/'knowledge.sqlite')\n");
 add('README.md','# 灵感一现可迁移阅读包\n\n范围：'+scope+(since?'（自 '+since+'）':'')+'。双击 index.html 离线阅读；wiki/ 是可用文本编辑器打开的 Markdown。data/ 只包含本次选择的分支；raw/ 保留已导入批次和全部已上传附件。\n\n运行 python restore_sqlite.py 可在本地生成 knowledge.sqlite；archive 表按 collection、id 保存完整 JSON。此包不含访问凭证，不能替代网站登录。文件副本编辑不自动回写线上。\n\n导出包含已成功上传的数据，不含仍在电脑等待上传的批次。各分支为导出时读取快照。可按 scope 分域或按 since 增量导出。\n');
 const manifest={schema_version:1,exported_at:now,scope,since,counts:{legacy:legacy?.records?.length||0,captures:tables.capture_items?.length||0,source_batches:tables.capture_batches?.length||0},files:[]};
 for(const [path,f] of Object.entries(files)){const bytes=typeof f==='string'?new TextEncoder().encode(f):f;manifest.files.push({path,bytes:bytes.length,sha256:await sha256(bytes)});}
 const manifestText=JSON.stringify(manifest,null,2);
 const bytes=zipCapture({...files,'manifest.json':manifestText});
 return new Response(bytes,{headers:{'Content-Type':'application/zip','Content-Disposition':'attachment; filename="linggan-portable-'+now.slice(0,10)+'-'+scope+'.zip"','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','X-Linggan-Export-Scope':scope,'X-Linggan-Export-Bytes':String(size)}});
}





// ASSETS is injected by scripts/build.mjs. No private material enters this bundle.

const MAX_BYTES=2_000_000;
const SECURITY={'X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline' data:; img-src 'self' data: blob:; font-src 'self' data:; connect-src 'self'; frame-ancestors 'self' https://chatgpt.com; base-uri 'self'; object-src 'none'"};
function json(body,status=200,headers={}){return new Response(JSON.stringify(body),{status,headers:{...SECURITY,'Content-Type':'application/json; charset=utf-8','Cache-Control':'private, no-store','Vary':'Cookie, Authorization',...headers}});}
function equalSecret(a,b){if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length||!a.length)return false;let out=0;for(let i=0;i<a.length;i++)out|=a.charCodeAt(i)^b.charCodeAt(i);return out===0;}
function serviceAuthorized(request,env){const auth=request.headers.get('Authorization')||'';return equalSecret(auth,env.WORKSPACE_SERVICE_TOKEN?'Bearer '+env.WORKSPACE_SERVICE_TOKEN:'');}
function userIdentity(request,env){
 const userId=request.headers.get('oai-authenticated-user-id'),email=request.headers.get('oai-authenticated-user-email');
 const signedIn=Boolean(userId&&email),owner=signedIn&&Boolean(env.WORKSPACE_OWNER_EMAIL)&&email.trim().toLowerCase()===env.WORKSPACE_OWNER_EMAIL.trim().toLowerCase();
 let name='我的空间';if(owner&&request.headers.get('oai-authenticated-user-full-name-encoding')==='percent-encoded-utf-8'){try{name=decodeURIComponent(request.headers.get('oai-authenticated-user-full-name')||'我的空间');}catch{}}
 return {signedIn,owner,displayName:owner?name:null,modelAnalysis:'not_connected',analysisMode:'evidence_compiler'};
}
async function parseBody(request){if(Number(request.headers.get('Content-Length')||0)>MAX_BYTES)throw Error('资料超过本版 2 MB 上限。');const raw=await request.text();if(new TextEncoder().encode(raw).length>MAX_BYTES)throw Error('资料超过本版 2 MB 上限。');return validateState(JSON.parse(raw));}
async function storedText(stored){if(!stored)return null;if(typeof stored.text==='function')return await stored.text();if(typeof stored.json==='function')return JSON.stringify(await stored.json());return null;}
function quoteRevision(state){return '"rev-'+(state?.revision||0)+'"';}
// 学习分支的版本号由内容本身计算，避免托管边缘改写响应头 ETag 后无法比对。
function learningRevision(text){let h=0x811c9dc5;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,0x01000193);}return 'lr-'+(h>>>0).toString(16).padStart(8,'0');}
async function bucketText(obj){if(typeof obj.text==='function')return obj.text();if(typeof obj.json==='function')return JSON.stringify(await obj.json());return typeof obj.body==='string'?obj.body:'';}
// 新增的写入协议不能删除历史：整份 PUT 时，任何已有编号消失都视为回退，必须拒绝。
function lostHistory(current,incoming){
 for(const key of ['records','sources','skills','actions','feedback','reviews','events','profiles','documents']){
  const ids=new Set((incoming?.[key]||[]).map(x=>x&&x.id));
  if((current?.[key]||[]).some(x=>x&&!ids.has(x.id)))return key;
 }
 if(current?.lab){
  if(!incoming?.lab)return 'lab';
  for(const key of ['models','observations','scenarios','states','experiments','configHistory']){
   const ids=new Set((incoming.lab[key]||[]).map(x=>x&&x.id));
   if((current.lab[key]||[]).some(x=>x&&!ids.has(x.id)))return 'lab.'+key;
  }
 }
 return null;
}
export default {
 async fetch(request,env,ctx){
  const url=new URL(request.url),path=url.pathname,started=Date.now(),rid=(request.headers.get('X-Request-Id')||'').slice(0,64)||crypto.randomUUID();
  let response;
  try{response=await handleRequest(request,env,ctx,url,path);}
  catch(error){response=handleFailure(error);}
  const headers=new Headers(response.headers);
  headers.set('X-Request-Id',rid);
  headers.set('Server-Timing','app;dur='+(Date.now()-started));
  console.log(JSON.stringify({event:'request',request_id:rid,method:request.method,path,status:response.status,duration_ms:Date.now()-started}));
  return new Response(response.body,{status:response.status,statusText:response.statusText,headers});
 },
 async scheduled(event,env,ctx){
  ctx.waitUntil(runDaily(env).catch(error=>console.error('cron_failed',error?.message||'Error')));
 }
};
function handleFailure(error){
 if(error instanceof SyntaxError)return json({message:'资料格式不是有效的 JSON。'},400);
 if(/资料|数据|记录|字段|编号|集合|口令|备份|操作|修改|保存/.test(error.message||''))return json({message:error.message},400);
 console.error('workspace_request_failed',error?.name||'Error');
 return json({message:'暂时无法完成操作，已保存的资料不会被覆盖。'},500);
}
async function handleRequest(request,env,ctx,url,path){
 try{
  // 健康检查只返回能力与时间，不暴露任何凭证或资料内容。
  if(path==='/api/health'&&['GET','HEAD'].includes(request.method))return json({ok:true,version:'4.2.0',time:new Date().toISOString(),timezone:'Asia/Shanghai',...await platformHealth(env)},200,{'Cache-Control':'no-store'});
  if(path==='/api/auth/login'&&request.method==='POST'){
   if(!env.DB)return json({message:'当前站点未配置数据库。'},503);
   const body=await request.json().catch(()=>({}));
   const result=await login(request,env,env.DB,body);
   return result.status===200?json(result.body,200,{'Set-Cookie':result.cookie}):json({message:result.message},result.status);
  }
  if(path==='/api/auth/logout'&&request.method==='POST'){
   const cookie=await logout(request,env,env.DB);
   return json({ok:true},200,{'Set-Cookie':cookie});
  }
  const workspace={load:async()=>(await createStore(env)).load(),apply:async ops=>(await createStore(env)).apply(ops)};
  const capture=await captureRoutes(request,env,{json,userIdentity,serviceAuthorized,STATE_KEY:'owner/digital-self-v2/workspace.json',LEARNING_KEY:'learning/public-records-v1.json',escapeHTML,workspace});if(capture)return capture;
  if(path==='/learning')return Response.redirect(url.origin+'/learning/'+url.search,308);
  if(path==='/learning/feed.json'&&request.method==='GET'){
   const stored=await env.BUCKET?.get('learning/public-records-v1.json');
   if(stored)return new Response(stored.body,{headers:{...SECURITY,'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','ETag':'"'+stored.etag+'"'}});
   const seed=ASSETS['/learning/records.json'];
   return new Response(Uint8Array.from(atob(seed.body),c=>c.charCodeAt(0)),{headers:{...SECURITY,'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'}});
  }
  if(path==='/api/learning-authoring'){
   const service=equalSecret(request.headers.get('Authorization')||'',env.LEARNING_SERVICE_TOKEN?'Bearer '+env.LEARNING_SERVICE_TOKEN:'');
   if(!service)return json({message:'学习分支写入需要授权。'},401);
   if(!env.BUCKET)return json({message:'学习存储尚未配置。'},503);
   const key='learning/public-records-v1.json',existing=await env.BUCKET.get(key);
   if(request.method==='GET'){
    if(!existing)return json({message:'尚未初始化。'},404);
    const text=await bucketText(existing),tag='"'+learningRevision(text)+'"';
    return new Response(text,{headers:{...SECURITY,'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','ETag':tag}});
   }
   if(request.method!=='PUT')return json({message:'仅支持读取或保存。'},405);
   if(existing){
    const current='"'+learningRevision(await bucketText(existing))+'"';
    const match=request.headers.get('If-Match');
    if(match!==current&&match!=='"'+existing.etag+'"')return json({message:'版本已变化，请重新读取并合并。'},409);
   }
   if(!existing&&request.headers.get('If-None-Match')!=='*')return json({message:'初始化需要显式防覆盖条件。'},428);
   const raw=await request.text();if(new TextEncoder().encode(raw).length>MAX_BYTES)return json({message:'资料超过上限。'},413);
   const value=JSON.parse(raw);
   if(value.schemaVersion!==1||!Array.isArray(value.articles)||!Array.isArray(value.methods)||!Array.isArray(value.history)||value.articles.length>1000)return json({message:'学习资料格式不正确。'},400);
   const ids=new Set();for(const a of value.articles){if(typeof a.id!=='string'||ids.has(a.id)||typeof a.title!=='string'||!Array.isArray(a.summary)||typeof a.url!=='string'||!a.url.startsWith('https://'))return json({message:'文章字段不正确或编号重复。'},400);ids.add(a.id);}
   if(existing){const old=JSON.parse(await bucketText(existing));if(old.articles.some(a=>!ids.has(a.id)))return json({message:'请保留已有文章，使用版本记录标记被替代内容。'},409);}
   const saved=await env.BUCKET.put(key,raw,{onlyIf:existing?{etagMatches:existing.etag}:{etagDoesNotMatch:'*'},httpMetadata:{contentType:'application/json'}});
   if(!saved)return json({message:'并发更新，本次没有覆盖。'},409);
   return json({status:'saved',articles:value.articles.length,methods:value.methods.length},200,{'ETag':'"'+learningRevision(raw)+'"'});
  }
  if(path==='/api/identity'){
   if(request.method!=='GET')return json({message:'此接口仅支持读取。'},405);
   const identity=userIdentity(request,env),session=authEnabled(env)?await sessionOwner(request,env):false;
   return json({...identity,owner:identity.owner||session,authMode:authEnabled(env)?'passcode':'sites',login:authEnabled(env)?'/login':'/signin-with-chatgpt'});
  }
  if(path.startsWith('/api/')){
   const service=serviceAuthorized(request,env),identity=userIdentity(request,env),session=authEnabled(env)?await sessionOwner(request,env):false,owner=identity.owner||session;
   if(!service&&!owner)return json({message:identity.signedIn?'当前账号无权读取此个人空间。':'请登录创建此空间的账号。'},401);
   if(!env.BUCKET)return json({message:'个人云端存储尚未配置，资料没有写入。'},503);
   if(!['GET','HEAD'].includes(request.method)&&!service&&request.headers.get('Origin')!==url.origin)return json({message:'请求来源不一致。'},403);
   if(path==='/api/bootstrap'){
    if(!service||request.method!=='POST')return json({message:'无权初始化。'},403);
    const store=await createStore(env),existing=await store.load().catch(()=>null);
    if(existing)return json({message:'个人资料已存在；初始化不会覆盖它。'},409);
    const state=await parseBody(request);state.mode='personal';state.revision=1;state.updatedAt=new Date().toISOString();
    await store.replace(state);
    return json({status:'saved',revision:1,records:state.records.length,sources:state.sources.length},201);
   }
   if(path==='/api/workspace/apply'){
    if(request.method!=='POST')return json({message:'此接口仅支持提交修改。'},405);
    if(Number(request.headers.get('Content-Length')||0)>MAX_BYTES)return json({message:'资料超过本版 2 MB 上限。'},413);
    const raw=await request.text();if(new TextEncoder().encode(raw).length>MAX_BYTES)return json({message:'资料超过本版 2 MB 上限。'},413);
    let payload;try{payload=JSON.parse(raw);}catch{return json({message:'修改内容不是有效的 JSON。'},400);}
    const store=await createStore(env),result=await store.apply(payload?.ops);
    return json({status:'saved',revision:result.revision,ops:result.ops},200);
   }
   if(path==='/api/workspace/backups'&&request.method==='GET')return json({items:await readBackupIndex(env)});
   if(path==='/api/workspace/backup'&&request.method==='POST'){
    const store=await createStore(env),result=await snapshot(env,store,{reason:'manual'});
    return json({status:'saved',...result},201);
   }
   if(path==='/api/workspace/restore'&&request.method==='POST'){
    const body=await request.json().catch(()=>({}));
    if(body?.confirm!==true)return json({message:'恢复会覆盖当前资料；请先下载备份并显式确认。'},400);
    const key=String(body.key||'');
    if(!key.startsWith('owner/digital-self-v2/backups/'))return json({message:'备份编号不正确。'},400);
    const stored=await env.BUCKET.get(key);
    if(!stored)return json({message:'找不到这份备份。'},404);
    let state=null;try{state=JSON.parse(await storedText(stored));}catch{state=null;}
    if(!state)return json({message:'备份内容无法解析。'},400);
    const store=await createStore(env);
    let before=null;try{before=await snapshot(env,store,{reason:'before-restore'});}catch{}
    const current=await store.load().catch(()=>null);
    state.revision=Math.max(Number(current?.state?.revision||0),Number(state.revision||0))+1;
    const result=await store.replace(state);
    return json({status:'restored',...result,beforeRestore:before?.key||null},200);
   }
   if(path==='/api/workspace'){
    const store=await createStore(env);
    if(request.method==='GET'){
     let loaded;try{loaded=await store.load();}catch{return json({message:'个人资料尚未完成初始化。'},404);}
     if(!loaded)return json({message:'个人资料尚未完成初始化。'},404);
     return new Response(JSON.stringify(loaded.state),{status:200,headers:{...SECURITY,'Content-Type':'application/json; charset=utf-8','Cache-Control':'private, no-store','Vary':'Cookie, Authorization','ETag':quoteRevision(loaded.state)}});
    }
    if(request.method==='PUT'){
     const match=request.headers.get('If-Match');if(!match)return json({message:'请先读取当前版本，再保存修改。'},428);
     const current=await store.load().catch(()=>null);
     if(!current){
      if(match!=='new')return json({message:'请先读取个人空间，再保存第一条记录。'},428);
      const state=await parseBody(request);state.mode='personal';state.revision=1;state.updatedAt=new Date().toISOString();
      await store.replace(state);
      return json({status:'saved',revision:1,updatedAt:state.updatedAt},201,{'ETag':'"rev-1"'});
     }
     if(match!==quoteRevision(current.state)&&match!=='new')return json({message:'其他页面已更新这份资料。请刷新后重试；本页修改仍保留。'},409);
     const incoming=await parseBody(request);
     const lost=lostHistory(current.state,incoming);
     if(lost)return json({message:'请保留已有资料与历史；如需停用，请使用修订或停用标记，不要删除记录。'},409);
     const ops=workspaceOps(current.state,incoming);
     if(!ops.length){const touched=await store.touch();return json({status:'saved',revision:touched.revision,updatedAt:new Date().toISOString()},200,{'ETag':'"rev-'+touched.revision+'"'});}
     const result=await store.apply(ops);
     return json({status:'saved',revision:result.revision,updatedAt:new Date().toISOString()},200,{'ETag':'"rev-'+result.revision+'"'});
    }
    return json({message:'不支持的资料操作。'},405);
   }
   if(path==='/api/notices'){
    if(request.method!=='GET')return json({message:'此接口仅支持读取。'},405);
    if(!env.DB)return json({items:[]});
    const rows=await env.DB.prepare('SELECT id,kind,title,body,created_at AS createdAt FROM ds_notice WHERE read_at IS NULL ORDER BY created_at DESC LIMIT 20').all();
    return json({items:rows.results||[]});
   }
   if(path.startsWith('/api/notices/')&&request.method==='POST'&&env.DB){
    const id=path.slice('/api/notices/'.length);
    await env.DB.prepare('UPDATE ds_notice SET read_at=? WHERE id=?').bind(new Date().toISOString(),id).run();
    return json({ok:true});
   }
   return json({message:'找不到这个接口。'},404);
  }
  if(!['GET','HEAD'].includes(request.method))return json({message:'不支持的请求。'},405);
  let assetPath=path==='/'?'/index.html':path==='/learning'||path==='/learning/'?'/learning/index.html':path==='/guide'||path==='/guide/'?'/guide/index.html':path==='/login'||path==='/login/'?'/login/index.html':path;
  if(assetPath.startsWith('/downloads/'))assetPath='/guide'+assetPath;
  const asset=ASSETS[assetPath];if(!asset)return new Response('页面不存在。',{status:404,headers:SECURITY});
  const bytes=Uint8Array.from(atob(asset.body),c=>c.charCodeAt(0));
  return new Response(request.method==='HEAD'?null:bytes,{headers:{...SECURITY,'Content-Type':asset.type,'Cache-Control':/\.(html|js|css)$/.test(assetPath)?'no-cache':'public, max-age=300'}});
 }catch(error){throw error;}
}
